import type { PackageApi } from "../../../types/api/PackageApi";
import { MobileShellApplication } from "../../apps/mobile-shell/view/MobileShellApplication";
import { PlayerShellApplication } from "../../apps/player-shell/view/PlayerShellApplication";
import { StarterWorkbenchApplication } from "../../apps/starter-workbench/view/StarterWorkbenchApplication";
import { openMobileUi } from "../open-mobile-ui";
import { getMobileUiMode } from "../settings/activation-settings";

export function createPackageApi(): PackageApi {
  return {
    getMobileUiMode,
    isMobileUiActive() {
      return getMobileUiMode() !== "none";
    },
    async openDiagnosticWorkbench() {
      await new StarterWorkbenchApplication().render(true);
    },
    async openMobileJournals(options) {
      await new MobileShellApplication(options).render(true);
    },
    openMobileUi,
    async openPlayerUi(options) {
      await new PlayerShellApplication(options).render(true);
    },
  };
}
