import type { OnTheGoOptions } from "../../types/api/OnTheGoOptions";
import { MobileShellApplication } from "../apps/mobile-shell/view/MobileShellApplication";
import { PlayerShellApplication } from "../apps/player-shell/view/PlayerShellApplication";
import { getMobileUiMode } from "./settings/activation-settings";

export async function openMobileUi(options: OnTheGoOptions = {}): Promise<void> {
  const Application = game.user.isGM ? MobileShellApplication : PlayerShellApplication;
  await new Application(options).render(true);
}

export async function openMobileUiIfActive(): Promise<void> {
  if (getMobileUiMode() !== "none") await openMobileUi();
}
