export function readBrowserFullscreenState(page: Document) {
  return {
    active: Boolean(page.fullscreenElement),
    supported:
      page.fullscreenEnabled === true &&
      typeof page.documentElement.requestFullscreen === "function" &&
      typeof page.exitFullscreen === "function",
  };
}

export async function toggleBrowserFullscreen(page: Document): Promise<void> {
  if (page.fullscreenElement) {
    await page.exitFullscreen();
    return;
  }

  if (!readBrowserFullscreenState(page).supported) {
    throw new Error("Browser fullscreen is unavailable.");
  }

  // Keep Foundry's other windows and native roll dialogs inside the fullscreen element too.
  // Called directly from the button gesture, before any unrelated asynchronous work.
  await page.documentElement.requestFullscreen({ navigationUI: "hide" });
}
