<script setup lang="ts">
import type { MobileJournalEntry } from "../../../../types/mobile-journal";
import type {
  PlayerActions,
  PlayerActivityMessage,
  PlayerCharacter,
} from "../../../../types/player-character";
import { usePlayerSheetStore } from "../state/player-sheet-store";
import AbilitiesSection from "./abilities/AbilitiesSection.vue";
import AdvancementSection from "./advancement/AdvancementSection.vue";
import ChatSection from "./chat/ChatSection.vue";
import CombatSection from "./combat/CombatSection.vue";
import EffectsSection from "./effects/EffectsSection.vue";
import InventorySection from "./inventory/InventorySection.vue";
import JournalsSection from "./journals/JournalsSection.vue";
import MagicSection from "./magic/MagicSection.vue";
import NotesSection from "./notes/NotesSection.vue";
import ReligionSection from "./religion/ReligionSection.vue";
import SkillsSection from "./skills/SkillsSection.vue";
import StatusSection from "./status/StatusSection.vue";

defineProps<{
  actions: PlayerActions;
  activity: PlayerActivityMessage[];
  character: PlayerCharacter;
  journalError?: string | undefined;
  journals: MobileJournalEntry[];
}>();

const store = usePlayerSheetStore();
</script>

<template>
  <div
    class="tw:min-h-0 tw:flex-1 tw:overscroll-contain"
    :class="
      ['chat', 'journals'].includes(store.activeDestination)
        ? 'tw:overflow-hidden'
        : 'tw:overflow-y-auto'
    "
  >
    <StatusSection
      v-if="store.activeDestination === 'status'"
      :actions="actions"
      :character="character"
    />
    <SkillsSection
      v-else-if="store.activeDestination === 'skills'"
      :actions="actions"
      :skills="character.skills"
    />
    <AbilitiesSection
      v-else-if="store.activeDestination === 'abilities'"
      :actions="actions"
      :talents="character.talents"
      :traits="character.traits"
    />
    <CombatSection
      v-else-if="store.activeDestination === 'combat'"
      :actions="actions"
      :character="character"
    />
    <InventorySection
      v-else-if="store.activeDestination === 'inventory'"
      :actions="actions"
      :inventory="character.inventory"
    />
    <MagicSection
      v-else-if="store.activeDestination === 'magic'"
      :actions="actions"
      :spells="character.magic.spells"
    />
    <ReligionSection
      v-else-if="store.activeDestination === 'religion'"
      :actions="actions"
      :god="character.god"
      :prayers="character.magic.prayers"
    />
    <EffectsSection
      v-else-if="store.activeDestination === 'effects'"
      :actions="actions"
      :effects="character.effects"
    />
    <NotesSection
      v-else-if="store.activeDestination === 'notes'"
      :actions="actions"
      :character="character"
    />
    <AdvancementSection
      v-else-if="store.activeDestination === 'advancement'"
      :actions="actions"
      :character="character"
    />
    <ChatSection v-else-if="store.activeDestination === 'chat'" :activity="activity" />
    <JournalsSection v-else :error="journalError" :journals="journals" />
  </div>
</template>
