import {
  type AdvanceCostTables,
  calculateAdvanceCost,
  calculateTalentAdvanceCost,
  spendExperience,
} from "../../functions/player-sheet/advancement";
import { asRecord, readNestedNumber, readNumber } from "../value-readers";
import { getActorItem, getActorItems, getCurrentCharacterActor, getItemSystem } from "./data";

type AdvancementType = "characteristic" | "skill";

export function getAdvanceCost(advances: number, type: AdvancementType, modifier = 0): number {
  return calculateAdvanceCost(getConfiguredAdvanceCosts()[type], advances, modifier);
}

export function getConfiguredAdvanceCosts(): AdvanceCostTables {
  return {
    characteristic: getConfiguredAdvanceCostTable("characteristic"),
    skill: getConfiguredAdvanceCostTable("skill"),
  };
}

function getConfiguredAdvanceCostTable(type: AdvancementType): number[] {
  const configured = game.wfrp4e?.config?.xpCost?.[type];

  if (
    !Array.isArray(configured) ||
    configured.length === 0 ||
    !configured.every((cost) => typeof cost === "number")
  ) {
    throw new Error(`The WFRP ${type} advancement costs are unavailable.`);
  }

  return configured;
}

export async function advanceCurrentPlayerCharacteristic(characteristicKey: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const system = asRecord(actor.system);
  const characteristics = asRecord(system?.["characteristics"]);
  const characteristic = asRecord(characteristics?.[characteristicKey]);

  if (!characteristic) {
    throw new Error("That characteristic is no longer available.");
  }

  const advances = readNumber(characteristic["advances"]) ?? 0;
  const cost = getAdvanceCost(
    advances,
    "characteristic",
    readNumber(characteristic["costModifier"]) ?? 0,
  );
  const spent = assertAffordable(system, cost);
  const changes: Record<string, unknown> = {
    [`system.characteristics.${characteristicKey}.advances`]: advances + 1,
    "system.details.experience.spent": spent,
  };
  addExperienceLog(changes, actor, cost, characteristicKey.toUpperCase(), spent);
  await actor.update(changes, { skipExperienceChecks: true });
}

export async function advanceCurrentPlayerSkill(skillId: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const item = getActorItem(actor, skillId, ["skill"]);
  const system = asRecord(actor.system);
  const itemSystem = getItemSystem(item);
  const advances = readNestedNumber(itemSystem, "advances", "value") ?? 0;
  const modifier = readNestedNumber(itemSystem, "advances", "costModifier") ?? 0;
  const cost = getAdvanceCost(advances, "skill", modifier);
  const spent = assertAffordable(system, cost);
  const changes: Record<string, unknown> = {
    "items": [{ "_id": item.id, "system.advances.value": advances + 1 }],
    "system.details.experience.spent": spent,
  };
  addExperienceLog(changes, actor, cost, item.name, spent);
  await actor.update(changes, { skipExperienceChecks: true });
}

export async function advanceCurrentPlayerTalent(talentId: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const item = getActorItem(actor, talentId, ["talent"]);
  const system = asRecord(actor.system);
  const ranks = getActorItems(actor)
    .filter((candidate) => candidate.type === "talent" && candidate.name === item.name)
    .reduce(
      (total, candidate) =>
        total + (readNestedNumber(getItemSystem(candidate), "advances", "value") ?? 1),
      0,
    );
  const cost = calculateTalentAdvanceCost(ranks);
  const spent = assertAffordable(system, cost);
  const changes: Record<string, unknown> = { "system.details.experience.spent": spent };
  addExperienceLog(changes, actor, cost, item.name, spent);

  if (!actor.createEmbeddedDocuments || !item.toObject) {
    throw new Error("Talent advancement is unavailable.");
  }

  await actor.update(changes, { skipExperienceChecks: true });
  const talentData = item.toObject();
  delete talentData["_id"];
  delete talentData["id"];
  await actor.createEmbeddedDocuments("Item", [talentData]);
}

function assertAffordable(system: Record<string, unknown> | undefined, cost: number): number {
  const details = asRecord(system?.["details"]);
  const experience = asRecord(details?.["experience"]);
  const total = readNumber(experience?.["total"]);
  const spent = readNumber(experience?.["spent"]);

  if (total === undefined || spent === undefined) {
    throw new Error("The character experience values are unavailable.");
  }

  return spendExperience(total, spent, cost).spent;
}

function addExperienceLog(
  changes: Record<string, unknown>,
  actor: FoundryActor,
  cost: number,
  reason: string,
  spent: number,
): void {
  const system = asRecord(actor.system);
  const addToLog = system?.["addToExpLog"];

  if (typeof addToLog !== "function") {
    throw new Error("The WFRP experience log is unavailable.");
  }

  changes["system.details.experience.log"] = addToLog.call(actor.system, cost, reason, spent);
}
