import type {
  PlayerArmour,
  PlayerArmourLocation,
  PlayerCombat,
  PlayerWeapon,
} from "../../../types/player-character";
import {
  asRecord,
  readBoolean,
  readDescription,
  readEquipped,
  readNestedString,
  readNumeric,
  readString,
} from "../value-readers";
import { getItemId, getItemSystem, readStringArray } from "./data";

const LOCATIONS = [
  { key: "head", label: "Head" },
  { key: "lArm", label: "Left arm" },
  { key: "rArm", label: "Right arm" },
  { key: "body", label: "Body" },
  { key: "lLeg", label: "Left leg" },
  { key: "rLeg", label: "Right leg" },
] as const;

export function extractPlayerCombat(
  status: Record<string, unknown>,
  items: unknown[],
): PlayerCombat {
  return {
    armour: items.map(extractArmour).filter((item): item is PlayerArmour => item !== undefined),
    armourByLocation: extractDerivedArmour(status),
    weapons: items
      .map((item) => extractWeapon(item, items))
      .filter((item): item is PlayerWeapon => item !== undefined),
  };
}

function extractWeapon(item: unknown, items: unknown[]): PlayerWeapon | undefined {
  const record = asRecord(item);
  const system = getItemSystem(item);

  if (record?.["type"] !== "weapon" || !system) {
    return undefined;
  }

  const ammoId =
    readNestedString(system, "currentAmmo", "value") || readString(system["currentAmmo"]);
  const ammo = items.find((candidate) => getItemId(candidate) === ammoId);

  return {
    ammunitionName: readString(asRecord(ammo)?.["name"]),
    damage: readNestedString(system, "damage", "value"),
    descriptionHtml: readDescription(system),
    equipped: readEquipped(system),
    flaws: readStringArray(asRecord(system["flaws"])?.["value"]),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    loaded: readBoolean(asRecord(system["loaded"])?.["value"]),
    name: readString(record["name"]),
    qualities: readStringArray(asRecord(system["qualities"])?.["value"]),
    range: readNestedString(system, "range", "value"),
    reach: readNestedString(system, "reach", "value"),
    special: readNestedString(system, "special", "value"),
  };
}

function extractArmour(item: unknown): PlayerArmour | undefined {
  const record = asRecord(item);
  const system = getItemSystem(item);

  if (record?.["type"] !== "armour" || !system) {
    return undefined;
  }

  const armourPoints = asRecord(system["AP"]);

  return {
    descriptionHtml: readDescription(system),
    flaws: readStringArray(asRecord(system["flaws"])?.["value"]),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    locations: LOCATIONS.map(({ key, label }) => ({
      armourPoints: readNumeric(armourPoints?.[key]) ?? 0,
      key,
      label,
    })).filter((location) => location.armourPoints > 0),
    name: readString(record["name"]),
    qualities: readStringArray(asRecord(system["qualities"])?.["value"]),
    worn: readEquipped(system),
  };
}

function extractDerivedArmour(status: Record<string, unknown>): PlayerArmourLocation[] {
  const armour = asRecord(status["armour"]);

  return LOCATIONS.map(({ key, label }) => ({
    armourPoints:
      readNumeric(asRecord(armour?.[key])?.["value"]) ?? readNumeric(armour?.[key]) ?? 0,
    key,
    label,
  }));
}
