<script setup lang="ts">
import { ref } from "vue";

import type { MobileJournalEntry } from "../../../../types/mobile-journal";
import type { JournalFolder } from "./types";

defineOptions({
  name: "MobileJournalFolderTree",
});

const props = defineProps<{
  depth: number;
  folders: JournalFolder[];
  hasSearchQuery: boolean;
}>();

const emit = defineEmits<{
  openEntry: [entry: MobileJournalEntry];
}>();

const expandedFolderIds = ref(new Set(props.folders.map((folder) => folder.id)));

function toggleFolder(folderId: string): void {
  const nextFolderIds = new Set(expandedFolderIds.value);

  if (nextFolderIds.has(folderId)) {
    nextFolderIds.delete(folderId);
  } else {
    nextFolderIds.add(folderId);
  }

  expandedFolderIds.value = nextFolderIds;
}

function isFolderExpanded(folderId: string): boolean {
  return props.hasSearchQuery || expandedFolderIds.value.has(folderId);
}
</script>

<template>
  <div class="mobile-journal-shell__folders">
    <section
      v-for="folder in folders"
      :key="folder.id"
      class="mobile-journal-shell__folder"
      :style="{ '--folder-depth': depth }"
    >
      <button
        type="button"
        class="mobile-journal-shell__folder-button"
        :aria-expanded="isFolderExpanded(folder.id)"
        @click="toggleFolder(folder.id)"
      >
        <i
          class="fa-solid"
          :class="isFolderExpanded(folder.id) ? 'fa-folder-open' : 'fa-folder'"
          aria-hidden="true"
        />
        <span>{{ folder.name }}</span>
        <small>{{ folder.journalCount }}</small>
        <i
          class="fa-solid fa-chevron-right mobile-journal-shell__folder-chevron"
          aria-hidden="true"
        />
      </button>

      <div v-if="isFolderExpanded(folder.id)" class="mobile-journal-shell__folder-entries">
        <MobileJournalFolderTree
          v-if="folder.folders.length > 0"
          :depth="depth + 1"
          :folders="folder.folders"
          :has-search-query="hasSearchQuery"
          @open-entry="emit('openEntry', $event)"
        />

        <button
          v-for="journal in folder.journals"
          :key="journal.id"
          type="button"
          class="mobile-journal-shell__journal-row"
          :style="{ '--folder-depth': depth + 1 }"
          @click="emit('openEntry', journal)"
        >
          <i class="fa-solid fa-book-open" aria-hidden="true" />
          <span>
            <strong>{{ journal.name }}</strong>
            <small>{{ journal.pages.length }} pages</small>
          </span>
        </button>
      </div>
    </section>
  </div>
</template>
