import { ref } from "vue";

export function usePlayerAction() {
  const actionMessage = ref("");
  const actionTone = ref<"error" | "success">("success");
  const isBusy = ref(false);

  async function runPlayerAction(action: () => Promise<void>, confirmation: string): Promise<void> {
    actionMessage.value = "";
    isBusy.value = true;

    try {
      await action();
      actionTone.value = "success";
      actionMessage.value = confirmation;
    } catch (error) {
      actionTone.value = "error";
      actionMessage.value =
        error instanceof Error ? error.message : "That action could not be completed.";
    } finally {
      isBusy.value = false;
    }
  }

  return { actionMessage, actionTone, isBusy, runPlayerAction };
}
