import type {
  MobileJournalEntry,
  MobileJournalPage,
  MobileJournalSource,
} from "../../../types/mobile-journal";
import { canCurrentUserObserve } from "./journal-permissions";

interface JournalSourceContext {
  idPrefix: string;
  source: MobileJournalSource;
}

interface PackWithDocuments {
  getDocuments: () => Promise<unknown>;
}

const WORLD_SOURCE: MobileJournalSource = {
  id: "world",
  label: "World Journals",
  type: "world",
};

export async function getMobileJournalEntries(
  respectPermissions = false,
): Promise<MobileJournalEntry[]> {
  const worldEntries = getWorldJournalEntries(respectPermissions);
  const compendiumEntries = await getCompendiumJournalEntries(respectPermissions);

  return [...worldEntries, ...compendiumEntries].sort(compareBySourceThenName);
}

export function getPlayerMobileJournalEntries(): Promise<MobileJournalEntry[]> {
  return getMobileJournalEntries(true);
}

function getWorldJournalEntries(respectPermissions: boolean): MobileJournalEntry[] {
  const sourceContext: JournalSourceContext = {
    idPrefix: "world",
    source: WORLD_SOURCE,
  };

  return getJournalDocuments()
    .filter((document) => !respectPermissions || canCurrentUserObserve(document))
    .map((document) => toMobileJournalEntry(document, sourceContext, respectPermissions))
    .filter((entry): entry is MobileJournalEntry => entry !== undefined);
}

async function getCompendiumJournalEntries(
  respectPermissions: boolean,
): Promise<MobileJournalEntry[]> {
  const entries: MobileJournalEntry[] = [];

  for (const pack of getJournalPacks()) {
    if (respectPermissions && !canCurrentUserObserve(pack)) {
      continue;
    }

    const packIdentity = getPackIdentity(pack);

    if (!packIdentity) {
      continue;
    }

    const sourceContext: JournalSourceContext = {
      idPrefix: `compendium:${packIdentity.id}`,
      source: {
        id: packIdentity.id,
        label: packIdentity.label,
        type: "compendium",
      },
    };

    const documents = await getPackDocuments(pack);
    entries.push(
      ...documents
        .filter((document) => !respectPermissions || canCurrentUserObserve(document))
        .map((document) => toMobileJournalEntry(document, sourceContext, respectPermissions))
        .filter((entry): entry is MobileJournalEntry => entry !== undefined),
    );
  }

  return entries;
}

function getJournalDocuments(): unknown[] {
  const journalCollection = game.journal;

  if (Array.isArray(journalCollection.contents)) {
    return journalCollection.contents;
  }

  return [];
}

function getJournalPacks(): unknown[] {
  return getCollectionContents(game.packs).filter(isJournalPack);
}

function isJournalPack(pack: unknown): boolean {
  if (!isRecord(pack)) {
    return false;
  }

  const documentName = getString(pack["documentName"]);
  const metadata = isRecord(pack["metadata"]) ? pack["metadata"] : {};
  const metadataType = getString(metadata["type"]) ?? getString(metadata["documentName"]);

  return documentName === "JournalEntry" || metadataType === "JournalEntry";
}

async function getPackDocuments(pack: unknown): Promise<unknown[]> {
  if (!isPackWithDocuments(pack)) {
    return [];
  }

  const documents = await pack.getDocuments();

  return Array.isArray(documents) ? documents : [];
}

function getPackIdentity(pack: unknown): undefined | { id: string; label: string } {
  if (!isRecord(pack)) {
    return undefined;
  }

  const metadata = isRecord(pack["metadata"]) ? pack["metadata"] : {};
  const id =
    getString(pack["collection"]) ?? getString(metadata["id"]) ?? getString(metadata["name"]);
  const label =
    getString(pack["title"]) ?? getString(pack["label"]) ?? getString(metadata["label"]) ?? id;

  if (!id || !label) {
    return undefined;
  }

  return { id, label };
}

function toMobileJournalEntry(
  document: unknown,
  sourceContext: JournalSourceContext,
  respectPermissions: boolean,
): MobileJournalEntry | undefined {
  if (!isRecord(document)) {
    return undefined;
  }

  const identity = getDocumentIdentity(document);

  if (!identity) {
    return undefined;
  }

  const folderName = getFolderPath(document["folder"]);
  const pages = getJournalPages(document["pages"], respectPermissions);
  const entry: MobileJournalEntry = {
    id: `${sourceContext.idPrefix}:${identity.id}`,
    name: identity.name,
    pages,
    source: sourceContext.source,
  };

  if (folderName) {
    entry.folderName = folderName;
  }

  return entry;
}

function getJournalPages(rawPages: unknown, respectPermissions: boolean): MobileJournalPage[] {
  return getCollectionContents(rawPages)
    .filter((document) => !respectPermissions || canCurrentUserObserve(document))
    .map(toMobileJournalPage)
    .filter((page): page is MobileJournalPage => page !== undefined)
    .sort((left, right) => left.sort - right.sort || left.name.localeCompare(right.name));
}

function toMobileJournalPage(document: unknown): MobileJournalPage | undefined {
  if (!isRecord(document)) {
    return undefined;
  }

  const identity = getDocumentIdentity(document);

  if (!identity) {
    return undefined;
  }

  const text = isRecord(document["text"]) ? document["text"] : {};

  return {
    html: getString(text["content"]) ?? "",
    id: identity.id,
    name: identity.name,
    sort: getNumber(document["sort"]) ?? 0,
    type: getString(document["type"]) ?? "unknown",
  };
}

function getDocumentIdentity(
  document: Record<string, unknown>,
): undefined | { id: string; name: string } {
  const id = getString(document["id"]);
  const name = getString(document["name"]);

  if (!id || !name) {
    return undefined;
  }

  return { id, name };
}

function getCollectionContents(collection: unknown): unknown[] {
  if (Array.isArray(collection)) {
    return collection;
  }

  if (isRecord(collection) && Array.isArray(collection["contents"])) {
    return collection["contents"];
  }

  return [];
}

function getFolderPath(folder: unknown): string | undefined {
  if (!isRecord(folder)) {
    return undefined;
  }

  const names: string[] = [];
  let currentFolder: unknown = folder;

  while (isRecord(currentFolder)) {
    const name = getString(currentFolder["name"]);

    if (name) {
      names.unshift(name);
    }

    currentFolder = currentFolder["folder"];
  }

  return names.length > 0 ? names.join(" / ") : undefined;
}

function compareBySourceThenName(left: MobileJournalEntry, right: MobileJournalEntry): number {
  return (
    getSourceSort(left.source.type) - getSourceSort(right.source.type) ||
    left.source.label.localeCompare(right.source.label) ||
    left.name.localeCompare(right.name)
  );
}

function getSourceSort(sourceType: MobileJournalSource["type"]): number {
  if (sourceType === "world") {
    return 0;
  }

  return 1;
}

function getNumber(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  return undefined;
}

function getString(value: unknown): string | undefined {
  if (typeof value === "string" && value.trim() !== "") {
    return value;
  }

  return undefined;
}

function isPackWithDocuments(value: unknown): value is PackWithDocuments {
  return isRecord(value) && typeof value["getDocuments"] === "function";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
