import { asRecord, readNumeric, readString } from "../value-readers";

export function getActorItems(actor: FoundryActor): FoundryItem[] {
  const items = Array.isArray(actor.items.contents) ? actor.items.contents : [];
  return items.filter(isFoundryItem);
}

export function getCurrentCharacterActor(): FoundryActor {
  const actor = game.user.character;

  if (!actor || actor.type !== "character") {
    throw new Error("No supported player character is assigned.");
  }

  return actor;
}

export function getActorItem(
  actor: FoundryActor,
  itemId: string,
  expectedTypes?: string[],
): FoundryItem {
  const item = getActorItems(actor).find((candidate) => candidate.id === itemId);

  if (!item || (expectedTypes && !expectedTypes.includes(item.type))) {
    throw new Error("That character entry is no longer available.");
  }

  return item;
}

export function getItemSystem(item: unknown): Record<string, unknown> | undefined {
  return asRecord(asRecord(item)?.["system"]);
}

export function getItemId(item: unknown): string {
  const record = asRecord(item);
  return readString(record?.["id"]) || readString(record?.["_id"]);
}

export function getCollectionContents(collection: unknown): unknown[] {
  if (Array.isArray(collection)) {
    return collection;
  }

  const record = asRecord(collection);
  return Array.isArray(record?.["contents"]) ? record["contents"] : [];
}

export function readStringArray(value: unknown): string[] {
  return Array.isArray(value)
    ? value
        .map((entry) => {
          if (typeof entry === "string") {
            return entry;
          }

          const record = asRecord(entry);
          const name = readString(record?.["display"] || record?.["name"] || record?.["label"]);
          const amount = readNumeric(record?.["value"]);
          return name && amount ? `${name} ${amount}` : name;
        })
        .filter(Boolean)
    : [];
}

function isFoundryItem(value: unknown): value is FoundryItem {
  const record = asRecord(value);
  return Boolean(
    record &&
    readString(record["id"]) &&
    readString(record["type"]) &&
    typeof record["update"] === "function",
  );
}
