import { calculateTalentAdvanceCost } from "../../functions/player-sheet/advancement";
import { compareByName } from "../../functions/player-sheet/sorting";
import type { PlayerCareer, PlayerTalent, PlayerTrait } from "../../../types/player-character";
import {
  asRecord,
  readBoolean,
  readDescription,
  readEnabledKeys,
  readNestedBoolean,
  readNestedNumber,
  readNestedNumeric,
  readNestedString,
  readString,
} from "../value-readers";
import { getItemSystem, readStringArray } from "./data";

export function extractTalents(items: FoundryItem[]): PlayerTalent[] {
  const talents = new Map<string, PlayerTalent>();

  for (const item of items.filter((candidate) => candidate.type === "talent")) {
    const system = getItemSystem(item);
    const existing = talents.get(item.name);
    const ranks = readNestedNumber(system, "advances", "value") ?? 1;

    if (existing) {
      existing.ranks += ranks;
      existing.nextAdvanceCost = calculateTalentAdvanceCost(existing.ranks);
    } else {
      talents.set(item.name, {
        descriptionHtml: readDescription(system),
        id: item.id,
        name: item.name,
        nextAdvanceCost: calculateTalentAdvanceCost(ranks),
        ranks,
        tests: readNestedString(system, "tests", "value"),
      });
    }
  }

  return [...talents.values()].sort(compareByName);
}

export function extractTraits(items: FoundryItem[]): PlayerTrait[] {
  return items
    .filter((item) => item.type === "trait")
    .map((item) => {
      const system = getItemSystem(item);
      return {
        descriptionHtml: readDescription(system),
        id: item.id,
        name: item.name,
        rollable: readNestedBoolean(system, "rollable", "value"),
        specification: readNestedString(system, "specification", "value"),
      };
    })
    .sort(compareByName);
}

export function extractCareer(
  details: Record<string, unknown>,
  items: FoundryItem[],
): PlayerCareer {
  const item = items.find((candidate) => {
    const system = getItemSystem(candidate);
    return (
      candidate.type === "career" &&
      (readNestedBoolean(system, "current", "value") || readBoolean(system?.["current"]))
    );
  });
  const system = item ? getItemSystem(item) : undefined;
  const derived = asRecord(details["career"]);
  const name = item?.name || readString(derived?.["name"]) || readString(derived?.["value"]);
  const skillNames = uniqueNames([
    ...readStringArray(system?.["skills"]),
    ...readStringArray(system?.["addedSkills"]),
  ]);

  return {
    characteristicAdvances: readCareerCharacteristics(system?.["characteristics"]),
    complete: readNestedBoolean(system, "complete", "value") || readBoolean(system?.["complete"]),
    descriptionHtml: readDescription(system),
    group: readNestedString(system, "careergroup", "value"),
    id: item?.id ?? "",
    level: readNestedNumeric(system, "level", "value") ?? 0,
    name: name || "No current career",
    skillNames,
    talentNames: readStringArray(system?.["talents"]),
  };
}

function readCareerCharacteristics(value: unknown): string[] {
  const arrayValues = readStringArray(value);
  return arrayValues.length ? arrayValues : readEnabledKeys(value);
}

function uniqueNames(names: string[]): string[] {
  const seen = new Set<string>();
  return names.filter((name) => {
    const normalized = name.trim().toLowerCase();
    if (!normalized || seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
}
