<script setup lang="ts">
import type {
  PlayerActions,
  PlayerAilment,
  PlayerCondition,
  PlayerEffects,
  PlayerExtendedTest,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  effects: PlayerEffects;
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();

function changeCondition(condition: PlayerCondition, delta: number): void {
  void runPlayerAction(
    () =>
      delta > 0
        ? props.actions.addCondition(condition.id)
        : props.actions.removeCondition(condition.id),
    `${condition.name} updated.`,
  );
}

function rollExtendedTest(test: PlayerExtendedTest): void {
  void runPlayerAction(
    () => props.actions.rollExtendedTest(test.id),
    `${test.name} result sent to chat.`,
  );
}

function ailmentSubtitle(ailment: PlayerAilment): string {
  const details = ailment.details.map((detail) => `${detail.label}: ${detail.value}`).join(" · ");
  return details ? `${ailment.type} · ${details}` : ailment.type;
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Effects and health">
    <SectionHeading eyebrow="What ails you" title="Effects & Health" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:grid tw:gap-2" aria-labelledby="conditions-heading">
      <div class="tw:flex tw:items-center tw:justify-between">
        <h3 id="conditions-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
          Conditions
        </h3>
        <span class="tw:dui-badge tw:dui-badge-sm">Immediate controls</span>
      </div>
      <div class="tw:grid tw:gap-2 tw:min-[360px]:grid-cols-2">
        <article
          v-for="condition in effects.conditions"
          :key="condition.id"
          class="tw:grid tw:grid-cols-[minmax(0,1fr)_auto] tw:items-center tw:gap-2 tw:rounded-box tw:border tw:border-base-300 tw:bg-base-200 tw:p-3"
          :class="{ 'tw:border-secondary/60': condition.value > 0 }"
        >
          <div class="tw:min-w-0">
            <strong class="tw:block tw:[overflow-wrap:anywhere]">{{ condition.name }}</strong>
            <small class="tw:opacity-65">Current {{ condition.value }}</small>
          </div>
          <div class="tw:dui-join">
            <button
              type="button"
              class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11"
              :disabled="isBusy || condition.value <= 0"
              :aria-label="`Remove one ${condition.name}`"
              @click="changeCondition(condition, -1)"
            >
              −
            </button>
            <button
              type="button"
              class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11"
              :disabled="isBusy"
              :aria-label="`Add one ${condition.name}`"
              @click="changeCondition(condition, 1)"
            >
              +
            </button>
          </div>
        </article>
      </div>
    </section>

    <section
      v-if="effects.extendedTests.length"
      class="tw:grid tw:gap-2"
      aria-labelledby="extended-heading"
    >
      <h3 id="extended-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Extended tests
      </h3>
      <DescriptionCollapse
        v-for="test in effects.extendedTests"
        :key="test.id"
        :description-html="test.descriptionHtml"
        :image-url="test.imageUrl"
        :subtitle="`${test.test} · ${test.difficulty || 'Challenging'}`"
        :title="test.name"
      >
        <template #badge>
          <span class="tw:dui-badge tw:dui-badge-secondary tw:dui-badge-sm"
            >{{ test.currentSL }} / {{ test.targetSL }} SL</span
          >
        </template>
        <progress
          class="tw:dui-progress tw:dui-progress-secondary"
          :value="test.currentSL"
          :max="Math.max(1, test.targetSL)"
        />
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-primary tw:min-h-11 tw:w-full"
          :disabled="isBusy"
          @click="rollExtendedTest(test)"
        >
          <i class="fa-solid fa-dice-d20" aria-hidden="true" /> Continue test
        </button>
      </DescriptionCollapse>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="ailments-heading">
      <h3 id="ailments-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Injuries & Ailments
      </h3>
      <DescriptionCollapse
        v-for="ailment in effects.ailments"
        :key="ailment.id"
        :description-html="ailment.descriptionHtml"
        :image-url="ailment.imageUrl"
        :subtitle="ailmentSubtitle(ailment)"
        :title="ailment.name"
      />
      <p v-if="effects.ailments.length === 0" class="tw:m-0 tw:text-sm tw:opacity-65">
        No injuries, diseases, mutations, critical wounds, or psychology entries.
      </p>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="active-effects-heading">
      <h3 id="active-effects-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Active effects
      </h3>
      <DescriptionCollapse
        v-for="effect in effects.active"
        :key="effect.id"
        :description-html="effect.descriptionHtml"
        :image-url="effect.imageUrl"
        :subtitle="effect.source"
        :title="effect.name"
      >
        <template #badge>
          <span v-if="effect.disabled" class="tw:dui-badge tw:dui-badge-ghost tw:dui-badge-sm"
            >Disabled</span
          >
        </template>
      </DescriptionCollapse>
      <p v-if="effects.active.length === 0" class="tw:m-0 tw:text-sm tw:opacity-65">
        No additional active effects.
      </p>
    </section>
  </section>
</template>
