import type { OnTheGoOptions } from "../../../types/api/OnTheGoOptions";
import { FoundryVueApplication } from "./FoundryVueApplication";
import {
  activateMobileShellMode,
  deactivateMobileShellMode,
  MOBILE_SHELL_WINDOW_CLASS,
} from "./mobile-shell-mode";

export abstract class OnTheGoApplication extends FoundryVueApplication {
  readonly #fullScreen: boolean;

  constructor({ windowed = false }: OnTheGoOptions = {}) {
    // Foundry concatenates class arrays, so presentation classes cannot live in shared defaults.
    super(
      windowed
        ? {
            id: `${new.target.DEFAULT_OPTIONS["id"]}-windowed`,
            classes: ["wfrp-on-the-go-windowed-shell"],
            window: { resizable: true },
          }
        : { classes: [MOBILE_SHELL_WINDOW_CLASS], position: { left: 0, top: 0 } },
    );
    this.#fullScreen = !windowed;
  }

  protected override _replaceHTML(
    result: HTMLElement,
    content: HTMLElement,
    options: foundry.applications.types.ApplicationRenderOptions,
  ): void {
    if (this.#fullScreen) activateMobileShellMode(this);
    super._replaceHTML(result, content, options);
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    // A windowed instance must not release another full-screen instance's ownership.
    deactivateMobileShellMode(this);
    await super._preClose(options);
  }
}
