import type {
  PlayerCareer,
  PlayerCharacteristic,
  PlayerSkill,
  PlayerTalent,
} from "../../../types/player-character";

export function calculateAdvanceCost(
  costs: readonly number[],
  advances: number,
  modifier = 0,
): number {
  if (costs.length === 0 || costs.some((cost) => !Number.isFinite(cost) || cost < 0)) {
    throw new Error("The WFRP advancement cost table is invalid.");
  }

  const index = Math.max(0, Math.floor(advances / 5));
  const cost = costs[Math.min(index, costs.length - 1)];

  if (cost === undefined) {
    throw new Error("The WFRP advancement cost table is incomplete.");
  }

  return cost + modifier;
}

export function calculateTalentAdvanceCost(ranks: number): number {
  return (ranks + 1) * 100;
}

export function spendExperience(total: number, spent: number, cost: number) {
  if (![total, spent, cost].every(Number.isFinite) || total < 0 || spent < 0 || cost < 0) {
    throw new Error("The character experience values are invalid.");
  }

  const available = total - spent;

  if (available < cost) {
    throw new Error(
      `This advance costs ${cost} XP, but only ${Math.max(0, available)} is available.`,
    );
  }

  const nextSpent = spent + cost;
  return { available: total - nextSpent, spent: nextSpent, total };
}
export interface AdvanceCostTables {
  characteristic: readonly number[];
  skill: readonly number[];
}

export interface CareerCharacteristicRequirement {
  advancesNeeded: number;
  characteristic: PlayerCharacteristic;
  complete: boolean;
}

export interface CareerSkillRequirement {
  advancesNeeded: number;
  complete: boolean;
  name: string;
  skill?: PlayerSkill;
}

export interface CareerAdvancementProgress {
  advanceTarget: number;
  characteristics: CareerCharacteristicRequirement[];
  completedRequirements: number;
  remainingAdvances: number;
  skills: CareerSkillRequirement[];
  talentComplete: boolean;
  talents: PlayerTalent[];
  totalRequirements: number;
}

export function getCareerAdvancementProgress(
  career: PlayerCareer,
  characteristics: PlayerCharacteristic[],
  skills: PlayerSkill[],
  talents: PlayerTalent[],
): CareerAdvancementProgress {
  const advanceTarget = Math.max(1, Math.floor(career.level)) * 5;
  const careerCharacteristicNames = new Set(career.characteristicAdvances.map(normalizeName));
  const characteristicRequirements = characteristics
    .filter((entry) =>
      [entry.key, entry.abbreviation, entry.label].some((value) =>
        careerCharacteristicNames.has(normalizeName(value)),
      ),
    )
    .map((characteristic) => requirement(characteristic, advanceTarget));
  const skillsByName = new Map(skills.map((skill) => [normalizeName(skill.name), skill]));
  const skillRequirements = uniqueNames(career.skillNames).map((name) => {
    const skill = skillsByName.get(normalizeName(name));
    const advances = skill?.advances ?? 0;
    return {
      advancesNeeded: Math.max(0, advanceTarget - advances),
      complete: advances >= advanceTarget,
      name,
      ...(skill ? { skill } : {}),
    };
  });
  const careerTalentNames = new Set(career.talentNames.map(normalizeName));
  const careerTalents = talents.filter((talent) =>
    careerTalentNames.has(normalizeName(talent.name)),
  );
  const talentComplete = career.talentNames.length === 0 || careerTalents.length > 0;
  const totalRequirements =
    characteristicRequirements.length +
    skillRequirements.length +
    (career.talentNames.length ? 1 : 0);
  const completedRequirements =
    characteristicRequirements.filter((entry) => entry.complete).length +
    skillRequirements.filter((entry) => entry.complete).length +
    (career.talentNames.length && talentComplete ? 1 : 0);

  return {
    advanceTarget,
    characteristics: characteristicRequirements,
    completedRequirements,
    remainingAdvances: [...characteristicRequirements, ...skillRequirements].reduce(
      (total, entry) => total + entry.advancesNeeded,
      0,
    ),
    skills: skillRequirements,
    talentComplete,
    talents: careerTalents,
    totalRequirements,
  };
}

function normalizeName(value: string): string {
  return value.trim().toLowerCase();
}

function requirement(
  characteristic: PlayerCharacteristic,
  advanceTarget: number,
): CareerCharacteristicRequirement {
  return {
    advancesNeeded: Math.max(0, advanceTarget - characteristic.advances),
    characteristic,
    complete: characteristic.advances >= advanceTarget,
  };
}

function uniqueNames(names: string[]): string[] {
  const seen = new Set<string>();
  return names.filter((name) => {
    const normalized = normalizeName(name);
    if (!normalized || seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
}
