import type { PlayerMagic, PlayerPrayer, PlayerSpell } from "../../../types/player-character";
import { compareByName } from "../../functions/player-sheet/sorting";
import {
  asRecord,
  readDescription,
  readNestedBoolean,
  readNestedNumber,
  readNestedString,
  readString,
} from "../value-readers";
import { getItemId, getItemSystem } from "./data";

export function extractPlayerMagic(items: unknown[]): PlayerMagic {
  return {
    prayers: items
      .map(extractPrayer)
      .filter((item): item is PlayerPrayer => item !== undefined)
      .sort(compareByName),
    spells: items
      .map(extractSpell)
      .filter((item): item is PlayerSpell => item !== undefined)
      .sort(compareByName),
  };
}

function extractSpell(item: unknown): PlayerSpell | undefined {
  const record = asRecord(item);
  const system = getItemSystem(item);

  if (record?.["type"] !== "spell" || !system) {
    return undefined;
  }

  return {
    castingNumber: readNestedNumber(system, "cn", "value") ?? 0,
    channellingSL: readNestedNumber(system, "cn", "SL") ?? 0,
    damage: readNestedString(system, "damage", "value"),
    descriptionHtml: readDescription(system),
    duration: readNestedString(system, "duration", "value"),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    lore: readNestedString(system, "lore", "value"),
    memorized: readNestedBoolean(system, "memorized", "value"),
    name: readString(record["name"]),
    range: readNestedString(system, "range", "value"),
    target: readNestedString(system, "target", "value"),
  };
}

function extractPrayer(item: unknown): PlayerPrayer | undefined {
  const record = asRecord(item);
  const system = getItemSystem(item);

  if (record?.["type"] !== "prayer" || !system) {
    return undefined;
  }

  return {
    damage: readNestedString(system, "damage", "value"),
    descriptionHtml: readDescription(system),
    duration: readNestedString(system, "duration", "value"),
    god: readNestedString(system, "god", "value"),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    name: readString(record["name"]),
    range: readNestedString(system, "range", "value"),
    target: readNestedString(system, "target", "value"),
    type: readNestedString(system, "type", "value"),
  };
}
