import type { Component } from "vue";

import type { MobileJournalEntry } from "../../../../types/mobile-journal";

import PlayerShellApp from "./PlayerShellApp.vue";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../../constants";
import { getPlayerMobileJournalEntries } from "../../../foundry/journals/mobile-journal-adapter";
import { getCurrentPlayerCharacter } from "../../../wfrp/player-character-adapter";
import { currentPlayerActions } from "../../../wfrp/player/actions";
import { getPlayerActivityMessages } from "../../../wfrp/player/activity";
import { OnTheGoApplication } from "../../../foundry/apps/OnTheGoApplication";

export class PlayerShellApplication extends OnTheGoApplication {
  #hookIds: Array<[string, number]> = [];
  #journalError = "";
  #journals: MobileJournalEntry[] = [];
  #journalsLoaded = false;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${PACKAGE_ID}-player-shell`,
    classes: [PACKAGE_ID],
    tag: "section",
    window: {
      title: `${PACKAGE_TITLE} Character`,
      icon: "fa-solid fa-shield-halved",
      resizable: false,
    },
    position: {
      width: 430,
      height: 800,
    },
  };

  protected override getVueComponent(): Component {
    return PlayerShellApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      actions: currentPlayerActions,
      activity: getPlayerActivityMessages(),
      characterState: getCurrentPlayerCharacter(),
      journalError: this.#journalError,
      journals: this.#journals,
    };
  }

  protected override async _renderHTML(
    context: foundry.applications.types.ApplicationRenderContext,
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<HTMLElement> {
    const [result] = await Promise.all([super._renderHTML(context, options), this.loadJournals()]);
    return result;
  }

  protected override _replaceHTML(
    result: HTMLElement,
    content: HTMLElement,
    options: foundry.applications.types.ApplicationRenderOptions,
  ): void {
    super._replaceHTML(result, content, options);
    this.registerRefreshHooks();
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    for (const [hook, hookId] of this.#hookIds) {
      Hooks.off(hook, hookId);
    }

    this.#hookIds = [];
    await super._preClose(options);
  }

  private registerRefreshHooks(): void {
    if (this.#hookIds.length > 0) {
      return;
    }

    this.#hookIds.push([
      "updateActor",
      Hooks.on("updateActor", (actor) => {
        if (actor.id === game.user.character?.id) {
          void this.render(true);
        }
      }),
    ]);

    for (const hook of ["createItem", "deleteItem", "updateItem"] as const) {
      this.#hookIds.push([
        hook,
        Hooks.on(hook, (item) => {
          if (item.parent?.id === game.user.character?.id) {
            void this.render(true);
          }
        }),
      ]);
    }

    for (const hook of [
      "createActiveEffect",
      "deleteActiveEffect",
      "updateActiveEffect",
    ] as const) {
      this.#hookIds.push([
        hook,
        Hooks.on(hook, (effect) => {
          const parent = effect.parent;
          const actorId = parent?.id;
          const owningActorId = parent && "parent" in parent ? parent.parent?.id : undefined;

          if (actorId === game.user.character?.id || owningActorId === game.user.character?.id) {
            void this.render(true);
          }
        }),
      ]);
    }

    for (const hook of ["createChatMessage", "deleteChatMessage", "updateChatMessage"] as const) {
      this.#hookIds.push([
        hook,
        Hooks.on(hook, () => {
          void this.render(true);
        }),
      ]);
    }

    for (const hook of [
      "createJournalEntry",
      "deleteJournalEntry",
      "updateJournalEntry",
      "createJournalEntryPage",
      "deleteJournalEntryPage",
      "updateJournalEntryPage",
    ] as const) {
      this.#hookIds.push([
        hook,
        Hooks.on(hook, () => {
          this.#journalsLoaded = false;
          void this.render(true);
        }),
      ]);
    }
  }

  private async loadJournals(): Promise<void> {
    if (this.#journalsLoaded) {
      return;
    }

    try {
      this.#journals = await getPlayerMobileJournalEntries();
      this.#journalError = "";
    } catch (error) {
      this.#journals = [];
      this.#journalError =
        error instanceof Error ? error.message : "The available journals could not be loaded.";
      console.error(`${PACKAGE_TITLE} could not load player journals.`, error);
    } finally {
      this.#journalsLoaded = true;
    }
  }
}
