import type { CreatePlayerInventoryItem, PlayerActions } from "../../../types/player-character";
import type { FoundryTestData } from "../../../types/foundry";
import { adjustResourceValue } from "../../functions/player-sheet/resources";
import {
  toggleCurrentPlayerInventoryEquipped,
  updateCurrentPlayerInventoryQuantity,
} from "../player-inventory-adapter";
import { asRecord, readNumeric } from "../value-readers";
import {
  advanceCurrentPlayerCharacteristic,
  advanceCurrentPlayerSkill,
  advanceCurrentPlayerTalent,
} from "./advancement";
import { getActorItem, getActorItems, getCurrentCharacterActor } from "./data";
import { updateCurrentPlayerNotes } from "./notes";

const DIRECT_RESOURCES = new Set([
  "corruption",
  "criticalWounds",
  "fate",
  "fortune",
  "resilience",
  "resolve",
  "sin",
]);

export const currentPlayerActions: PlayerActions = {
  addCondition: async (conditionId) => {
    const actor = getCurrentCharacterActor();
    assertMethod(actor.addCondition, "Condition controls are unavailable.");
    await actor.addCondition(conditionId, 1);
  },
  addCareerSkill: addCurrentPlayerCareerSkill,
  adjustResource: adjustCurrentPlayerResource,
  advanceCharacteristic: advanceCurrentPlayerCharacteristic,
  advanceSkill: advanceCurrentPlayerSkill,
  advanceTalent: advanceCurrentPlayerTalent,
  createInventoryItem: createCurrentPlayerInventoryItem,
  deleteInventoryItem: deleteCurrentPlayerInventoryItem,
  moveInventoryItem: moveCurrentPlayerInventoryItem,
  openCareerSelector: openCurrentPlayerCareerSelector,
  reloadWeapon: reloadCurrentPlayerWeapon,
  removeCondition: async (conditionId) => {
    const actor = getCurrentCharacterActor();
    assertMethod(actor.removeCondition, "Condition controls are unavailable.");
    await actor.removeCondition(conditionId, 1);
  },
  rollCharacteristic: async (key) => {
    const actor = getCurrentCharacterActor();
    assertMethod(actor.setupCharacteristic, "Characteristic tests are unavailable.");
    await rollConfiguredTest(() => actor.setupCharacteristic!(key));
  },
  rollExtendedTest: async (itemId) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["extendedTest"]);
    assertMethod(actor.setupExtendedTest, "Extended tests are unavailable.");
    await actor.setupExtendedTest(item);
  },
  rollPrayer: async (itemId) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["prayer"]);
    assertMethod(actor.setupPrayer, "Prayer tests are unavailable.");
    await rollConfiguredTest(() => actor.setupPrayer!(item));
  },
  rollSkill: async (itemId) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["skill"]);
    assertMethod(actor.setupSkill, "Skill tests are unavailable.");
    await rollConfiguredTest(() => actor.setupSkill!(item));
  },
  rollSpell: async (itemId, mode) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["spell"]);
    const setup = mode === "channel" ? actor.setupChannell : actor.setupCast;
    assertMethod(setup, `${mode === "channel" ? "Channelling" : "Casting"} is unavailable.`);
    await rollConfiguredTest(() => setup.call(actor, item));
  },
  rollTrait: async (itemId) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["trait"]);
    assertMethod(actor.setupTrait, "Trait tests are unavailable.");
    await rollConfiguredTest(() => actor.setupTrait!(item));
  },
  rollWeapon: async (itemId) => {
    const actor = getCurrentCharacterActor();
    const item = getActorItem(actor, itemId, ["weapon"]);
    assertMethod(actor.setupWeapon, "Weapon tests are unavailable.");
    await rollConfiguredTest(() => actor.setupWeapon!(item));
  },
  setCareerComplete: async (careerId, complete) => {
    const actor = getCurrentCharacterActor();
    await getActorItem(actor, careerId, ["career"]).update({ "system.complete.value": complete });
  },
  toggleInventoryEquipped: toggleCurrentPlayerInventoryEquipped,
  updateInventoryQuantity: updateCurrentPlayerInventoryQuantity,
  updateNotes: updateCurrentPlayerNotes,
};

async function addCurrentPlayerCareerSkill(skillName: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const normalizedName = skillName.trim().toLowerCase();

  if (!normalizedName) throw new Error("That career skill is unavailable.");
  if (
    getActorItems(actor).some(
      (item) => item.type === "skill" && item.name.trim().toLowerCase() === normalizedName,
    )
  ) {
    return;
  }

  const findSkill = game.wfrp4e?.utility?.findSkill;
  assertMethod(findSkill, "The WFRP skill library is unavailable.");
  const skill = await findSkill(skillName);
  const skillData = skill.toObject?.();

  if (!skillData) throw new Error(`The ${skillName} skill could not be prepared.`);
  assertMethod(actor.createEmbeddedDocuments, "Adding skills is unavailable.");
  await actor.createEmbeddedDocuments("Item", [skillData], { career: true });
}

async function rollConfiguredTest(setup: () => Promise<FoundryTestData>): Promise<void> {
  const test = await setup();

  if (!test || typeof test.roll !== "function") {
    throw new Error("The WFRP test setup was cancelled or unavailable.");
  }

  await test.roll();
}

async function adjustCurrentPlayerResource(resourceKey: string, delta: number): Promise<void> {
  const actor = getCurrentCharacterActor();

  if (resourceKey === "wounds") {
    assertMethod(actor.modifyWounds, "Wound controls are unavailable.");
    await actor.modifyWounds(delta);
    return;
  }

  if (resourceKey === "advantage") {
    assertMethod(actor.modifyAdvantage, "Advantage controls are unavailable.");
    await actor.modifyAdvantage(delta);
    return;
  }

  if (!DIRECT_RESOURCES.has(resourceKey)) {
    throw new Error("That resource cannot be changed here.");
  }

  const system = asRecord(actor.system);
  const status = asRecord(system?.["status"]);
  const resource = asRecord(status?.[resourceKey]);
  const current = readNumeric(resource?.["value"]);
  const maximum = readNumeric(resource?.["max"]);

  if (current === undefined) {
    throw new Error("That resource is no longer available.");
  }

  const next = adjustResourceValue(current, delta, maximum);
  await actor.update({ [`system.status.${resourceKey}.value`]: next });
}

async function createCurrentPlayerInventoryItem(item: CreatePlayerInventoryItem): Promise<void> {
  const actor = getCurrentCharacterActor();
  const name = item.name.trim();

  if (!name) {
    throw new Error("Enter a name for the new item.");
  }

  assertMethod(actor.createEmbeddedDocuments, "Creating items is unavailable.");
  await actor.createEmbeddedDocuments("Item", [{ name, type: item.type }]);
}

async function deleteCurrentPlayerInventoryItem(itemId: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  getActorItem(actor, itemId, ["ammunition", "armour", "container", "money", "trapping", "weapon"]);
  assertMethod(actor.deleteEmbeddedDocuments, "Deleting items is unavailable.");
  await actor.deleteEmbeddedDocuments("Item", [itemId]);
}

async function moveCurrentPlayerInventoryItem(itemId: string, containerId: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const item = getActorItem(actor, itemId);

  if (containerId) {
    getActorItem(actor, containerId, ["container"]);
  }

  await item.update({ "system.location.value": containerId });
}

async function reloadCurrentPlayerWeapon(weaponId: string): Promise<void> {
  const actor = getCurrentCharacterActor();
  const weapon = getActorItem(actor, weaponId, ["weapon"]);

  if (actor.rollReloadTest) {
    await actor.rollReloadTest(weapon);
  } else if (actor.checkReloadExtendedTest) {
    await actor.checkReloadExtendedTest(weapon, actor);
  } else {
    throw new Error("Reload tests are unavailable.");
  }
}

async function openCurrentPlayerCareerSelector(): Promise<void> {
  const actor = getCurrentCharacterActor();
  const CareerSelector = game.wfrp4e?.apps?.CareerSelector;

  if (!CareerSelector) {
    throw new Error("The WFRP career selector is unavailable.");
  }

  await Promise.resolve(new CareerSelector(actor).render(true));
}

function assertMethod<T>(method: T | undefined, message: string): asserts method is T {
  if (typeof method !== "function") {
    throw new Error(message);
  }
}
