<script setup lang="ts">
import type {
  PlayerActions,
  PlayerTalent,
  PlayerTrait,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  talents: PlayerTalent[];
  traits: PlayerTrait[];
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();

function roll(trait: PlayerTrait): void {
  void runPlayerAction(() => props.actions.rollTrait(trait.id), `${trait.name} test sent to chat.`);
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Talents and traits">
    <SectionHeading
      :count="talents.length + traits.length"
      eyebrow="Gifts and abilities"
      title="Talents & Traits"
    />
    <p class="tw:m-0 tw:text-sm tw:opacity-70">Tap any entry to open its complete rules text.</p>
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:grid tw:gap-2" aria-labelledby="talents-heading">
      <h3 id="talents-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">Talents</h3>
      <DescriptionCollapse
        v-for="talent in talents"
        :key="talent.id || talent.name"
        :description-html="talent.descriptionHtml"
        :subtitle="talent.tests ? `Tests: ${talent.tests}` : 'No test specialization'"
        :title="talent.name"
      >
        <template #icon><i class="fa-solid fa-star" aria-hidden="true" /></template>
        <template #badge>
          <span class="tw:dui-badge tw:dui-badge-soft tw:dui-badge-sm"
            >Rank {{ talent.ranks }}</span
          >
        </template>
      </DescriptionCollapse>
      <p v-if="talents.length === 0" class="tw:m-0 tw:text-sm tw:opacity-65">
        No talents recorded.
      </p>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="traits-heading">
      <h3 id="traits-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">Traits</h3>
      <DescriptionCollapse
        v-for="trait in traits"
        :key="trait.id"
        :description-html="trait.descriptionHtml"
        :subtitle="trait.specification"
        :title="trait.name"
      >
        <template #icon><i class="fa-solid fa-paw" aria-hidden="true" /></template>
        <template #badge>
          <span v-if="trait.rollable" class="tw:dui-badge tw:dui-badge-secondary tw:dui-badge-sm">
            Rollable
          </span>
        </template>
        <button
          v-if="trait.rollable"
          type="button"
          class="tw:dui-btn tw:dui-btn-primary tw:min-h-11 tw:w-full"
          :disabled="isBusy"
          @click="roll(trait)"
        >
          <i class="fa-solid fa-dice-d20" aria-hidden="true" />
          Set up trait test
        </button>
      </DescriptionCollapse>
      <p v-if="traits.length === 0" class="tw:m-0 tw:text-sm tw:opacity-65">No traits recorded.</p>
    </section>
  </section>
</template>
