<script setup lang="ts">
import { computed } from "vue";

import { getCareerAdvancementProgress } from "../../../../functions/player-sheet/advancement";
import type {
  PlayerActions,
  PlayerCharacter,
  PlayerCharacteristic,
  PlayerSkill,
  PlayerTalent,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import ConfirmAction from "../common/ConfirmAction.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  character: PlayerCharacter;
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const careerProgress = computed(() =>
  getCareerAdvancementProgress(
    props.character.career,
    props.character.characteristics,
    props.character.skills,
    props.character.talents,
  ),
);

function advanceCharacteristic(characteristic: PlayerCharacteristic): void {
  void runPlayerAction(
    () => props.actions.advanceCharacteristic(characteristic.key),
    `${characteristic.label} advanced for ${characteristic.nextAdvanceCost} XP.`,
  );
}

function advanceSkill(skill: PlayerSkill): void {
  void runPlayerAction(
    () => props.actions.advanceSkill(skill.id),
    `${skill.name} advanced for ${skill.nextAdvanceCost} XP.`,
  );
}

function addCareerSkill(skillName: string): void {
  void runPlayerAction(
    () => props.actions.addCareerSkill(skillName),
    `${skillName} added to the character sheet.`,
  );
}

function advanceTalent(talent: PlayerTalent): void {
  void runPlayerAction(
    () => props.actions.advanceTalent(talent.id),
    `${talent.name} advanced for ${talent.nextAdvanceCost} XP.`,
  );
}

function toggleCareerComplete(): void {
  const complete = !props.character.career.complete;
  void runPlayerAction(
    () => props.actions.setCareerComplete(props.character.career.id, complete),
    complete ? "Career marked complete." : "Career marked incomplete.",
  );
}

function openCareerSelector(): void {
  void runPlayerAction(props.actions.openCareerSelector, "Career selector opened.");
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Advancement">
    <SectionHeading eyebrow="Spend experience" title="Advancement" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <div class="tw:dui-stats tw:grid tw:grid-cols-3 tw:bg-base-200 tw:shadow-md">
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Available</div>
        <div class="tw:dui-stat-value tw:text-xl tw:text-secondary">
          {{ character.experience.available }}
        </div>
      </div>
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Spent</div>
        <div class="tw:dui-stat-value tw:text-xl">{{ character.experience.spent }}</div>
      </div>
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Total</div>
        <div class="tw:dui-stat-value tw:text-xl">{{ character.experience.total }}</div>
      </div>
    </div>

    <DescriptionCollapse
      :description-html="character.career.descriptionHtml"
      :subtitle="
        [character.career.group, character.career.level && `Level ${character.career.level}`]
          .filter(Boolean)
          .join(' · ')
      "
      :title="character.career.name"
    >
      <template #icon><i class="fa-solid fa-briefcase" aria-hidden="true" /></template>
      <template #badge>
        <span
          class="tw:dui-badge tw:dui-badge-sm"
          :class="character.career.complete ? 'tw:dui-badge-success' : 'tw:dui-badge-warning'"
          >{{ character.career.complete ? "Complete" : "In progress" }}</span
        >
      </template>
      <p v-if="character.career.talentNames.length" class="tw:m-0 tw:text-sm">
        <strong>Career talents:</strong> {{ character.career.talentNames.join(", ") }}
      </p>
      <div class="tw:grid tw:gap-2 tw:min-[360px]:grid-cols-2">
        <button
          type="button"
          class="tw:dui-btn tw:min-h-11"
          :disabled="isBusy || !character.career.id"
          @click="toggleCareerComplete"
        >
          <i class="fa-solid fa-check-double" aria-hidden="true" /> Mark
          {{ character.career.complete ? "incomplete" : "complete" }}
        </button>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-secondary tw:min-h-11"
          :disabled="isBusy"
          @click="openCareerSelector"
        >
          <i class="fa-solid fa-route" aria-hidden="true" /> Change career
        </button>
      </div>
    </DescriptionCollapse>

    <div
      v-if="careerProgress.totalRequirements"
      class="tw:grid tw:gap-2 tw:rounded-box tw:bg-base-200 tw:p-3"
    >
      <div class="tw:flex tw:items-center tw:justify-between tw:gap-2 tw:text-sm">
        <strong>Career completion</strong>
        <span class="tw:dui-badge tw:dui-badge-sm tw:dui-badge-outline">
          {{ careerProgress.completedRequirements }}/{{ careerProgress.totalRequirements }} ready
        </span>
      </div>
      <progress
        class="tw:dui-progress"
        :value="careerProgress.completedRequirements"
        :max="careerProgress.totalRequirements"
        aria-label="Career completion requirements"
      />
      <small class="tw:opacity-70">
        {{ careerProgress.remainingAdvances }} characteristic and skill advances remain.
        <template v-if="character.career.talentNames.length">
          {{ careerProgress.talentComplete ? "Career talent owned." : "Choose 1 career talent." }}
        </template>
      </small>
    </div>

    <section class="tw:grid tw:gap-2" aria-labelledby="advance-characteristics-heading">
      <h3 id="advance-characteristics-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Career characteristics
      </h3>
      <article
        v-for="requirement in careerProgress.characteristics"
        :key="requirement.characteristic.key"
        class="tw:grid tw:grid-cols-[auto_minmax(0,1fr)_auto] tw:items-center tw:gap-3 tw:rounded-box tw:bg-base-200 tw:p-3"
      >
        <strong
          class="tw:grid tw:size-11 tw:place-items-center tw:rounded-field tw:bg-base-300 tw:font-serif tw:text-xl tw:text-secondary"
          >{{ requirement.characteristic.value }}</strong
        >
        <span class="tw:min-w-0"
          ><span class="tw:flex tw:flex-wrap tw:items-center tw:gap-2"
            ><strong>{{ requirement.characteristic.label }}</strong
            ><span
              class="tw:dui-badge tw:dui-badge-sm"
              :class="requirement.complete ? 'tw:dui-badge-success' : 'tw:dui-badge-warning'"
              >{{
                requirement.complete ? "Complete" : `${requirement.advancesNeeded} needed`
              }}</span
            ></span
          ><small class="tw:block tw:opacity-65"
            >{{ requirement.characteristic.advances }}/{{ careerProgress.advanceTarget }} career
            advances · {{ requirement.characteristic.nextAdvanceCost }} XP next</small
          ></span
        >
        <ConfirmAction
          :body="`Spend ${requirement.characteristic.nextAdvanceCost} XP to advance ${requirement.characteristic.label}?`"
          :danger="false"
          confirm-label="Spend XP"
          icon="fa-solid fa-arrow-up"
          :title="`Advance ${requirement.characteristic.label}?`"
          trigger-label="Advance"
          @confirm="advanceCharacteristic(requirement.characteristic)"
        />
      </article>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="advance-skills-heading">
      <h3 id="advance-skills-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Career skills
      </h3>
      <article
        v-for="requirement in careerProgress.skills"
        :key="requirement.name"
        class="tw:grid tw:grid-cols-[auto_minmax(0,1fr)_auto] tw:items-center tw:gap-3 tw:rounded-box tw:bg-base-200 tw:p-3"
        :class="{ 'tw:opacity-65': !requirement.skill }"
      >
        <strong
          class="tw:grid tw:size-11 tw:place-items-center tw:rounded-field tw:bg-base-300 tw:font-serif tw:text-xl tw:text-secondary"
          >{{ requirement.skill?.total ?? "—" }}</strong
        >
        <span class="tw:min-w-0"
          ><span class="tw:flex tw:flex-wrap tw:items-center tw:gap-2"
            ><strong class="tw:[overflow-wrap:anywhere]">{{ requirement.name }}</strong
            ><span
              class="tw:dui-badge tw:dui-badge-sm"
              :class="requirement.complete ? 'tw:dui-badge-success' : 'tw:dui-badge-warning'"
              >{{
                requirement.complete ? "Complete" : `${requirement.advancesNeeded} needed`
              }}</span
            ></span
          ><small class="tw:block tw:opacity-65">
            <template v-if="requirement.skill">
              {{ requirement.skill.advances }}/{{ careerProgress.advanceTarget }} career advances ·
              {{ requirement.skill.nextAdvanceCost }} XP next
            </template>
            <template v-else>Not on character sheet</template>
          </small></span
        >
        <ConfirmAction
          v-if="requirement.skill"
          :body="`Spend ${requirement.skill.nextAdvanceCost} XP to advance ${requirement.skill.name}?`"
          :danger="false"
          confirm-label="Spend XP"
          icon="fa-solid fa-arrow-up"
          :title="`Advance ${requirement.skill.name}?`"
          trigger-label="Advance"
          @confirm="advanceSkill(requirement.skill)"
        />
        <button
          v-else
          type="button"
          class="tw:dui-btn tw:dui-btn-sm tw:min-h-11"
          :disabled="isBusy"
          @click="addCareerSkill(requirement.name)"
        >
          Add to sheet
        </button>
      </article>
    </section>

    <section
      v-if="careerProgress.talents.length"
      class="tw:grid tw:gap-2"
      aria-labelledby="advance-talents-heading"
    >
      <h3 id="advance-talents-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Owned career talents
      </h3>
      <article
        v-for="talent in careerProgress.talents"
        :key="talent.id"
        class="tw:grid tw:grid-cols-[minmax(0,1fr)_auto] tw:items-center tw:gap-3 tw:rounded-box tw:bg-base-200 tw:p-3"
      >
        <span class="tw:min-w-0"
          ><strong class="tw:block tw:[overflow-wrap:anywhere]">{{ talent.name }}</strong
          ><small class="tw:opacity-65"
            >Rank {{ talent.ranks }} · {{ talent.nextAdvanceCost }} XP next</small
          ></span
        >
        <ConfirmAction
          :body="`Spend ${talent.nextAdvanceCost} XP to buy another rank of ${talent.name}?`"
          :danger="false"
          confirm-label="Spend XP"
          icon="fa-solid fa-arrow-up"
          :title="`Advance ${talent.name}?`"
          trigger-label="Advance"
          @confirm="advanceTalent(talent)"
        />
      </article>
    </section>
  </section>
</template>
