import type { Component } from "vue";

import ActivationSettingsApp from "./ActivationSettingsApp.vue";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../../constants";
import {
  getActivationSettingsUserRows,
  setEnabledUserIds,
} from "../../../foundry/settings/activation-settings";
import { FoundryVueApplication } from "../../../foundry/apps/FoundryVueApplication";

export class ActivationSettingsApplication extends FoundryVueApplication {
  static override DEFAULT_OPTIONS = {
    id: `${PACKAGE_ID}-activation-settings`,
    tag: "section",
    window: {
      title: `${PACKAGE_TITLE} Activation`,
      icon: "fa-solid fa-mobile-screen-button",
      resizable: true,
    },
    position: {
      width: 520,
      height: "auto",
    },
  };

  protected override getVueComponent(): Component {
    return ActivationSettingsApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      saveEnabledUserIds: setEnabledUserIds,
      users: getActivationSettingsUserRows(),
    };
  }
}
