<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";

import type { MobileJournalEntry, MobileJournalPage } from "../../../../types/mobile-journal";
import type { RenderedPage } from "./types";

const props = defineProps<{
  entry: MobileJournalEntry;
  pageId: string;
}>();

const emit = defineEmits<{
  "back": [];
  "update:pageId": [value: string];
}>();

const selectedHeaderId = ref("");
const pageScrollElement = ref<HTMLElement | null>(null);

const selectedPage = computed(() => {
  return props.entry.pages.find((page) => page.id === props.pageId) ?? props.entry.pages[0];
});

const selectedPageIndex = computed(() => {
  return props.entry.pages.findIndex((page) => page.id === selectedPage.value?.id);
});

const renderedPage = computed<RenderedPage>(() => {
  if (!selectedPage.value) {
    return {
      headers: [],
      html: "",
    };
  }

  return renderPageHtml(selectedPage.value);
});

const sourceLine = computed(() => {
  if (props.entry.folderName) {
    return `${props.entry.source.label} / ${props.entry.folderName}`;
  }

  return props.entry.source.label;
});

watch(
  () => props.pageId,
  () => {
    selectedHeaderId.value = "";
    void nextTick(() => {
      pageScrollElement.value?.scrollTo({ top: 0 });
    });
  },
);

function selectPreviousPage(): void {
  selectPageOffset(-1);
}

function selectNextPage(): void {
  selectPageOffset(1);
}

function updatePage(event: Event): void {
  const select = event.target;

  if (select instanceof HTMLSelectElement) {
    emit("update:pageId", select.value);
  }
}

function jumpToSelectedHeader(): void {
  if (!selectedHeaderId.value) {
    return;
  }

  document.getElementById(selectedHeaderId.value)?.scrollIntoView({
    behavior: "smooth",
    block: "start",
  });
}

function selectPageOffset(offset: number): void {
  const nextPage = props.entry.pages[selectedPageIndex.value + offset];

  if (nextPage) {
    emit("update:pageId", nextPage.id);
  }
}

function renderPageHtml(page: MobileJournalPage): RenderedPage {
  const parsedPage = new DOMParser().parseFromString(page.html, "text/html");
  const headingElements = [...parsedPage.body.querySelectorAll("h1, h2, h3, h4, h5, h6")];

  const headers = headingElements.map((headingElement, index) => {
    const text = headingElement.textContent.trim() || `Heading ${index + 1}`;
    const id = `otg-${page.id}-heading-${index}`;
    headingElement.id = id;

    return {
      id,
      level: Number(headingElement.tagName.slice(1)),
      text,
    };
  });

  return {
    headers,
    html: parsedPage.body.innerHTML,
  };
}
</script>

<template>
  <article v-if="selectedPage" class="mobile-journal-shell__reader">
    <header class="mobile-journal-shell__reader-bar">
      <button
        type="button"
        class="tw:dui-btn tw:dui-btn-square tw:dui-btn-ghost"
        aria-label="Back to journal list"
        @click="emit('back')"
      >
        <i class="fa-solid fa-chevron-left" aria-hidden="true" />
      </button>

      <div class="mobile-journal-shell__reader-title">
        <p>{{ sourceLine }}</p>
        <h2>{{ entry.name }}</h2>
      </div>
    </header>

    <div class="mobile-journal-shell__reader-controls">
      <button
        type="button"
        class="tw:dui-btn tw:dui-btn-square tw:dui-btn-ghost"
        aria-label="Previous page"
        :disabled="selectedPageIndex <= 0"
        @click="selectPreviousPage"
      >
        <i class="fa-solid fa-arrow-left" aria-hidden="true" />
      </button>

      <label class="mobile-journal-shell__select-control">
        <span>Page</span>
        <select :value="pageId" class="tw:dui-select" @change="updatePage">
          <option v-for="page in entry.pages" :key="page.id" :value="page.id">
            {{ page.name }}
          </option>
        </select>
      </label>

      <button
        type="button"
        class="tw:dui-btn tw:dui-btn-square tw:dui-btn-ghost"
        aria-label="Next page"
        :disabled="selectedPageIndex >= entry.pages.length - 1"
        @click="selectNextPage"
      >
        <i class="fa-solid fa-arrow-right" aria-hidden="true" />
      </button>

      <label
        v-if="renderedPage.headers.length > 0"
        class="mobile-journal-shell__select-control mobile-journal-shell__select-control--wide"
      >
        <span>Headings</span>
        <select v-model="selectedHeaderId" class="tw:dui-select" @change="jumpToSelectedHeader">
          <option value="">Jump to heading</option>
          <option v-for="header in renderedPage.headers" :key="header.id" :value="header.id">
            {{ "-".repeat(Math.max(0, header.level - 1)) }} {{ header.text }}
          </option>
        </select>
      </label>
    </div>

    <section ref="pageScrollElement" class="mobile-journal-shell__page">
      <h3>{{ selectedPage.name }}</h3>
      <!-- eslint-disable-next-line vue/no-v-html -- Foundry journal text pages are stored as HTML, and this GM-only reader preserves that content for read mode. -->
      <div class="mobile-journal-shell__content" v-html="renderedPage.html" />
    </section>
  </article>
</template>
