<script setup lang="ts">
import { nextTick, onMounted, ref } from "vue";

import type { PlayerActivityMessage } from "../../../../../types/player-character";
import SectionHeading from "../common/SectionHeading.vue";

defineProps<{
  activity: PlayerActivityMessage[];
}>();

const feed = ref<HTMLElement>();

onMounted(() => {
  void nextTick(() => feed.value?.scrollTo({ top: feed.value.scrollHeight }));
});

function formatTime(timestamp: number): string {
  return timestamp
    ? new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(timestamp)
    : "";
}
</script>

<template>
  <section class="tw:flex tw:h-full tw:min-h-0 tw:flex-col" aria-label="Chat and results">
    <header class="tw:grid tw:gap-2 tw:border-b tw:border-base-300 tw:bg-base-100 tw:p-3">
      <SectionHeading
        :count="activity.length"
        eyebrow="Live from the table"
        title="Chat & Results"
      />
      <div class="tw:flex tw:items-center tw:gap-2 tw:text-xs tw:opacity-70">
        <span class="tw:dui-status tw:dui-status-success" aria-hidden="true" />
        New visible messages appear automatically
      </div>
    </header>
    <div ref="feed" class="tw:min-h-0 tw:flex-1 tw:overflow-y-auto tw:p-3" aria-live="polite">
      <article
        v-for="message in activity"
        :key="message.id"
        class="tw:dui-chat"
        :class="message.isOwn ? 'tw:dui-chat-end' : 'tw:dui-chat-start'"
      >
        <div class="tw:dui-chat-header tw:flex tw:gap-2 tw:text-xs">
          <strong>{{ message.author }}</strong>
          <time v-if="message.timestamp" :datetime="new Date(message.timestamp).toISOString()">
            {{ formatTime(message.timestamp) }}
          </time>
        </div>
        <div
          class="tw:dui-chat-bubble tw:max-w-[92%] tw:bg-base-200 tw:text-base-content tw:shadow-md"
          :class="{ 'tw:border tw:border-secondary/50': message.isOwn }"
        >
          <p
            v-if="message.flavor"
            class="tw:mt-0 tw:mb-2 tw:text-xs tw:font-bold tw:text-secondary"
          >
            {{ message.flavor }}
          </p>
          <!-- eslint-disable-next-line vue/no-v-html -- Foundry chat content is permission-filtered, system-rendered rich HTML required to show WFRP roll cards. -->
          <div class="player-chat-content" v-html="message.contentHtml" />
        </div>
      </article>
      <div v-if="activity.length === 0" class="tw:dui-alert tw:items-start" role="status">
        <i class="fa-solid fa-comments tw:mt-1" aria-hidden="true" />
        <span>No visible chat messages yet. Tests and rolls will appear here.</span>
      </div>
    </div>
  </section>
</template>
