import type {
  PlayerCharacter,
  PlayerCharacterState,
  PlayerCharacteristic,
  PlayerExperience,
  PlayerResource,
  PlayerSkill,
} from "../../types/player-character";
import {
  type AdvanceCostTables,
  calculateAdvanceCost,
} from "../functions/player-sheet/advancement";
import { compareByName } from "../functions/player-sheet/sorting";
import { extractPlayerInventory } from "./player-inventory-adapter";
import { extractCareer, extractTalents, extractTraits } from "./player/abilities";
import { getConfiguredAdvanceCosts } from "./player/advancement";
import { extractPlayerCombat } from "./player/combat";
import { getActorItems, getItemSystem } from "./player/data";
import { extractNotes, extractPersonalDetails } from "./player/details";
import { extractPlayerEffects } from "./player/effects";
import { extractPlayerMagic } from "./player/magic";
import {
  asRecord,
  readDescription,
  readNestedNumber,
  readNestedNumeric,
  readNestedString,
  readNumber,
  readNumeric,
} from "./value-readers";

const CHARACTERISTICS = [
  ["WS", "ws", "Weapon Skill"],
  ["BS", "bs", "Ballistic Skill"],
  ["S", "s", "Strength"],
  ["T", "t", "Toughness"],
  ["I", "i", "Initiative"],
  ["Ag", "ag", "Agility"],
  ["Dex", "dex", "Dexterity"],
  ["Int", "int", "Intelligence"],
  ["WP", "wp", "Willpower"],
  ["Fel", "fel", "Fellowship"],
] as const;

export function getCurrentPlayerCharacter(): PlayerCharacterState {
  const actor = game.user.character;

  if (!actor) {
    return { status: "missing" };
  }

  if (actor.type !== "character") {
    return {
      actorName: actor.name,
      reason: "The assigned actor is not a WFRP4e player character.",
      status: "unsupported",
    };
  }

  let character: PlayerCharacter | undefined;

  try {
    character = extractPlayerCharacter(actor, getConfiguredAdvanceCosts());
  } catch (error) {
    return {
      actorName: actor.name,
      reason:
        error instanceof Error
          ? error.message
          : "The assigned character uses an unsupported WFRP4e runtime shape.",
      status: "unsupported",
    };
  }

  return character
    ? { character, status: "ready" }
    : {
        actorName: actor.name,
        reason: "The assigned character data does not match the supported WFRP4e shape.",
        status: "unsupported",
      };
}

function extractPlayerCharacter(
  actor: FoundryActor,
  advanceCosts: AdvanceCostTables,
): PlayerCharacter | undefined {
  const system = asRecord(actor.system);
  const status = asRecord(system?.["status"]);
  const details = asRecord(system?.["details"]);
  const wounds = extractResource(status, "wounds", "Wounds");

  if (!system || !status || !details || !wounds) {
    return undefined;
  }

  const characteristics = extractCharacteristics(system, advanceCosts.characteristic);

  if (!characteristics) {
    return undefined;
  }

  const items = getActorItems(actor);

  return {
    career: extractCareer(details, items),
    characteristics,
    combat: extractPlayerCombat(status, items),
    effects: extractPlayerEffects(actor, items),
    experience: extractExperience(details),
    god: readNestedString(details, "god", "value"),
    id: actor.id,
    imageUrl: actor.img,
    inventory: extractPlayerInventory(status, items),
    magic: extractPlayerMagic(items),
    movement: {
      move: readNestedNumeric(details, "move", "value") ?? 0,
      run: readNestedNumeric(details, "move", "run") ?? 0,
      walk: readNestedNumeric(details, "move", "walk") ?? 0,
    },
    name: actor.name,
    notes: extractNotes(details),
    personalDetails: extractPersonalDetails(details),
    resources: extractResources(status),
    skills: extractSkills(items, characteristics, advanceCosts.skill),
    species: readNestedString(details, "species", "value"),
    talents: extractTalents(items),
    traits: extractTraits(items),
    wounds,
  };
}

function extractCharacteristics(
  system: Record<string, unknown>,
  advanceCosts: readonly number[],
): PlayerCharacteristic[] | undefined {
  const raw = asRecord(system["characteristics"]);

  if (!raw) {
    return undefined;
  }

  const characteristics = CHARACTERISTICS.map<PlayerCharacteristic | undefined>(
    ([abbreviation, key, label]) => {
      const entry = asRecord(raw[key]);
      const value = readNumber(entry?.["value"]);
      return value === undefined
        ? undefined
        : {
            abbreviation,
            advances: readNumber(entry?.["advances"]) ?? 0,
            bonus: readNumber(entry?.["bonus"]) ?? Math.floor(value / 10),
            key,
            label,
            nextAdvanceCost: calculateAdvanceCost(
              advanceCosts,
              readNumber(entry?.["advances"]) ?? 0,
              readNumber(entry?.["costModifier"]) ?? 0,
            ),
            value,
          };
    },
  ).filter((entry): entry is PlayerCharacteristic => entry !== undefined);

  return characteristics.length === CHARACTERISTICS.length ? characteristics : undefined;
}

function extractResources(status: Record<string, unknown>): PlayerResource[] {
  return [
    extractResource(status, "fortune", "Fortune"),
    extractResource(status, "fate", "Fate"),
    extractResource(status, "resolve", "Resolve"),
    extractResource(status, "resilience", "Resilience"),
    extractResource(status, "advantage", "Advantage"),
    extractResource(status, "criticalWounds", "Critical wounds"),
    extractResource(status, "corruption", "Corruption"),
    extractResource(status, "sin", "Sin"),
  ].filter((resource): resource is PlayerResource => resource !== undefined);
}

function extractResource(
  status: Record<string, unknown> | undefined,
  key: string,
  label: string,
): PlayerResource | undefined {
  const raw = asRecord(status?.[key]);
  const current = readNumeric(raw?.["value"]);

  if (current === undefined) {
    return undefined;
  }

  const maximum = readNumeric(raw?.["max"]);
  return maximum === undefined ? { current, key, label } : { current, key, label, maximum };
}

function extractExperience(details: Record<string, unknown>): PlayerExperience {
  const experience = asRecord(details["experience"]);
  const total = readNumber(experience?.["total"]) ?? 0;
  const spent = readNumber(experience?.["spent"]) ?? 0;
  return { available: Math.max(0, total - spent), spent, total };
}

function extractSkills(
  items: FoundryItem[],
  characteristics: PlayerCharacteristic[],
  advanceCosts: readonly number[],
): PlayerSkill[] {
  const characteristicValues = new Map(characteristics.map((entry) => [entry.key, entry.value]));

  return items
    .filter((item) => item.type === "skill")
    .map((item) => {
      const system = getItemSystem(item);
      const characteristic = readNestedString(system, "characteristic", "value");
      const advances = readNestedNumber(system, "advances", "value") ?? 0;
      const modifier = readNestedNumber(system, "modifier", "value") ?? 0;
      return {
        advances,
        characteristic: characteristic.toUpperCase(),
        descriptionHtml: readDescription(system),
        id: item.id,
        name: item.name,
        nextAdvanceCost: calculateAdvanceCost(
          advanceCosts,
          advances,
          readNestedNumber(system, "advances", "costModifier") ?? 0,
        ),
        total:
          readNestedNumber(system, "total", "value") ??
          (characteristicValues.get(characteristic) ?? 0) + advances + modifier,
      };
    })
    .sort(compareByName);
}
