import type { PlayerActivityMessage } from "../../../types/player-character";
import { asRecord, readBoolean, readNumeric, readString } from "../value-readers";
import { getCollectionContents } from "./data";

const MAX_ACTIVITY_MESSAGES = 80;

export function getPlayerActivityMessages(): PlayerActivityMessage[] {
  return getCollectionContents(game.messages)
    .map(toActivityMessage)
    .filter((message): message is PlayerActivityMessage => message !== undefined)
    .sort((left, right) => left.timestamp - right.timestamp)
    .slice(-MAX_ACTIVITY_MESSAGES);
}

function toActivityMessage(message: unknown): PlayerActivityMessage | undefined {
  const record = asRecord(message);

  if (!record || record["visible"] !== true || record["isContentVisible"] !== true) {
    return undefined;
  }

  const id = readString(record["id"]);
  const contentHtml = readString(record["content"]);

  if (!id || !contentHtml) {
    return undefined;
  }

  const author = asRecord(record["author"] ?? record["user"]);
  const speaker = asRecord(record["speaker"]);
  const authorId = readString(author?.["id"]);

  return {
    author: readString(speaker?.["alias"]) || readString(author?.["name"]) || "The Old World",
    contentHtml,
    flavor: readString(record["flavor"]),
    id,
    isOwn: authorId ? authorId === game.user.id : readBoolean(record["isAuthor"]),
    timestamp: readNumeric(record["timestamp"] ?? record["time"]) ?? 0,
  };
}
