<script setup lang="ts">
import type { PlayerActions, PlayerSpell } from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  spells: PlayerSpell[];
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();

function useSpell(spell: PlayerSpell, mode: "cast" | "channel"): void {
  void runPlayerAction(
    () => props.actions.rollSpell(spell.id, mode),
    `${spell.name} ${mode === "cast" ? "casting" : "channelling"} result sent to chat.`,
  );
}
</script>

<template>
  <section class="tw:grid tw:gap-3 tw:p-3" aria-label="Magic">
    <SectionHeading :count="spells.length" eyebrow="The Winds of Magic" title="Spells" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />
    <div class="tw:grid tw:gap-2">
      <DescriptionCollapse
        v-for="spell in spells"
        :key="spell.id"
        :description-html="spell.descriptionHtml"
        :image-url="spell.imageUrl"
        :subtitle="
          [spell.lore, `CN ${spell.castingNumber}`, spell.memorized && 'Memorized']
            .filter(Boolean)
            .join(' · ')
        "
        :title="spell.name"
      >
        <template #badge>
          <span class="tw:dui-badge tw:dui-badge-soft tw:dui-badge-sm"
            >SL {{ spell.channellingSL }}</span
          >
        </template>
        <dl class="tw:m-0 tw:grid tw:grid-cols-2 tw:gap-2 tw:text-sm">
          <div v-if="spell.range">
            <dt class="tw:opacity-60">Range</dt>
            <dd class="tw:m-0 tw:font-bold">{{ spell.range }}</dd>
          </div>
          <div v-if="spell.target">
            <dt class="tw:opacity-60">Target</dt>
            <dd class="tw:m-0 tw:font-bold">{{ spell.target }}</dd>
          </div>
          <div v-if="spell.duration">
            <dt class="tw:opacity-60">Duration</dt>
            <dd class="tw:m-0 tw:font-bold">{{ spell.duration }}</dd>
          </div>
          <div v-if="spell.damage">
            <dt class="tw:opacity-60">Damage</dt>
            <dd class="tw:m-0 tw:font-bold">{{ spell.damage }}</dd>
          </div>
        </dl>
        <div class="tw:grid tw:grid-cols-2 tw:gap-2">
          <button
            type="button"
            class="tw:dui-btn tw:dui-btn-primary tw:min-h-11"
            :disabled="isBusy"
            @click="useSpell(spell, 'cast')"
          >
            <i class="fa-solid fa-wand-sparkles" aria-hidden="true" /> Cast
          </button>
          <button
            type="button"
            class="tw:dui-btn tw:min-h-11"
            :disabled="isBusy"
            @click="useSpell(spell, 'channel')"
          >
            <i class="fa-solid fa-bolt" aria-hidden="true" /> Channel
          </button>
        </div>
      </DescriptionCollapse>
    </div>
    <div v-if="spells.length === 0" class="tw:dui-alert tw:items-start" role="status">
      <i class="fa-solid fa-wand-sparkles tw:mt-1" aria-hidden="true" />
      <span>No spells are recorded on this character.</span>
    </div>
  </section>
</template>
