import type { Component } from "vue";

import type { MobileJournalEntry } from "../../../../types/mobile-journal";

import MobileShellApp from "./MobileShellApp.vue";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../../constants";
import { getMobileJournalEntries } from "../../../foundry/journals/mobile-journal-adapter";
import {
  getMobileActivationSettings,
  saveMobileActivationSettings,
  setForceMobileUi,
} from "../../../foundry/settings/activation-settings";
import { OnTheGoApplication } from "../../../foundry/apps/OnTheGoApplication";

export class MobileShellApplication extends OnTheGoApplication {
  #journals: MobileJournalEntry[] = [];

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${PACKAGE_ID}-mobile-shell`,
    classes: [PACKAGE_ID],
    tag: "section",
    window: {
      title: PACKAGE_TITLE,
      icon: "fa-solid fa-mobile-screen-button",
      resizable: false,
    },
    position: {
      width: 430,
      height: 800,
    },
  };

  protected override getVueComponent(): Component {
    return MobileShellApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      activationSettings: getMobileActivationSettings(),
      disableForcedMode: async () => {
        await setForceMobileUi(false);
      },
      journals: this.#journals,
      saveActivationSettings: saveMobileActivationSettings,
    };
  }

  protected override async _renderHTML(
    context: foundry.applications.types.ApplicationRenderContext,
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<HTMLElement> {
    const [result] = await Promise.all([super._renderHTML(context, options), this.loadJournals()]);

    return result;
  }

  private async loadJournals(): Promise<void> {
    this.#journals = await getMobileJournalEntries();
  }
}
