import { ActivationSettingsApplication } from "../../apps/activation-settings/view/ActivationSettingsApplication";
import { MobileShellApplication } from "../../apps/mobile-shell/view/MobileShellApplication";
import { StarterWorkbenchApplication } from "../../apps/starter-workbench/view/StarterWorkbenchApplication";
import { OpenWindowedOnTheGo } from "../apps/OpenWindowedOnTheGo";
import { PACKAGE_ID } from "../../constants";
import { registerActivationSettings } from "./activation-settings";

export function registerModuleSettings(): void {
  registerActivationSettings();

  game.settings.registerMenu(PACKAGE_ID, "enabledUsers", {
    name: "WFRP_ON_THE_GO.settings.activation.enabledUsers.name",
    label: "WFRP_ON_THE_GO.settings.activation.enabledUsers.label",
    hint: "WFRP_ON_THE_GO.settings.activation.enabledUsers.hint",
    icon: "fa-solid fa-mobile-screen-button",
    restricted: true,
    type: ActivationSettingsApplication,
  });

  game.settings.registerMenu(PACKAGE_ID, "openWindowedUi", {
    name: "WFRP_ON_THE_GO.settings.openWindowedUi.name",
    label: "WFRP_ON_THE_GO.settings.openWindowedUi.label",
    hint: "WFRP_ON_THE_GO.settings.openWindowedUi.hint",
    icon: "fa-solid fa-window-restore",
    restricted: false,
    type: OpenWindowedOnTheGo,
  });

  game.settings.registerMenu(PACKAGE_ID, "openDiagnosticWorkbench", {
    name: "WFRP_ON_THE_GO.settings.openDiagnosticWorkbench.name",
    label: "WFRP_ON_THE_GO.settings.openDiagnosticWorkbench.label",
    hint: "WFRP_ON_THE_GO.settings.openDiagnosticWorkbench.hint",
    icon: "fa-solid fa-window-restore",
    restricted: true,
    type: StarterWorkbenchApplication,
  });

  game.settings.registerMenu(PACKAGE_ID, "openMobileUi", {
    name: "WFRP_ON_THE_GO.settings.openMobileUi.name",
    label: "WFRP_ON_THE_GO.settings.openMobileUi.label",
    hint: "WFRP_ON_THE_GO.settings.openMobileUi.hint",
    icon: "fa-solid fa-mobile-screen-button",
    restricted: true,
    type: MobileShellApplication,
  });
}
