<script setup lang="ts">
import { computed, ref, watch } from "vue";

import type { PlayerActions, PlayerInventoryItem } from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import ConfirmAction from "../common/ConfirmAction.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  containers: PlayerInventoryItem[];
  item: PlayerInventoryItem;
}>();
const emit = defineEmits<{ back: [] }>();
const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const quantityDraft = ref(props.item.quantity);
const containerDraft = ref(props.item.containerId);
const quantityChanged = computed(() => quantityDraft.value !== props.item.quantity);

watch(
  () => [props.item.id, props.item.quantity, props.item.containerId] as const,
  ([, quantity, containerId]) => {
    quantityDraft.value = quantity;
    containerDraft.value = containerId;
  },
);

function updateQuantity(): void {
  if (!Number.isInteger(quantityDraft.value) || quantityDraft.value < 0) return;
  void runPlayerAction(
    () => props.actions.updateInventoryQuantity(props.item.id, quantityDraft.value),
    "Quantity updated.",
  );
}

function toggleEquipped(): void {
  void runPlayerAction(
    () => props.actions.toggleInventoryEquipped(props.item.id),
    props.item.equipped ? "Item unequipped." : "Item equipped.",
  );
}

function moveItem(): void {
  void runPlayerAction(
    () => props.actions.moveInventoryItem(props.item.id, containerDraft.value),
    containerDraft.value ? "Item moved into container." : "Item moved to carried gear.",
  );
}

function deleteItem(): void {
  void runPlayerAction(
    () => props.actions.deleteInventoryItem(props.item.id),
    "Item deleted.",
  ).then(() => {
    if (actionTone.value === "success") emit("back");
  });
}
</script>

<template>
  <article class="tw:grid tw:gap-4 tw:p-3" aria-label="Inventory item">
    <nav class="tw:dui-breadcrumbs tw:text-sm" aria-label="Inventory location">
      <ul>
        <li>
          <button type="button" class="tw:font-bold tw:text-secondary" @click="emit('back')">
            Inventory
          </button>
        </li>
        <li>{{ item.name }}</li>
      </ul>
    </nav>
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:dui-card tw:dui-card-border tw:overflow-hidden tw:bg-base-200 tw:shadow-lg">
      <figure class="tw:relative tw:h-40 tw:bg-base-300">
        <img
          v-if="item.imageUrl"
          :src="item.imageUrl"
          :alt="`${item.name} illustration`"
          width="400"
          height="240"
          class="tw:h-full tw:w-full tw:object-cover"
        />
        <div v-else class="tw:grid tw:h-full tw:place-items-center tw:text-4xl tw:text-secondary">
          <i class="fa-solid fa-sack-xmark" aria-hidden="true" />
        </div>
        <span
          v-if="item.equipped"
          class="tw:dui-badge tw:dui-badge-secondary tw:absolute tw:top-3 tw:right-3"
          >Equipped</span
        >
      </figure>
      <div class="tw:dui-card-body tw:gap-4 tw:p-4">
        <div>
          <p class="tw:m-0 tw:text-xs tw:font-black tw:text-secondary tw:uppercase">
            {{ item.category }}
          </p>
          <h2 class="tw:dui-card-title tw:font-serif tw:text-2xl">{{ item.name }}</h2>
        </div>
        <dl class="tw:grid tw:grid-cols-2 tw:rounded-box tw:bg-base-300">
          <div class="tw:p-3">
            <dt class="tw:text-xs tw:opacity-65">Encumbrance</dt>
            <dd class="tw:m-0 tw:font-serif tw:text-2xl tw:font-bold">{{ item.encumbrance }}</dd>
          </div>
          <div class="tw:p-3">
            <dt class="tw:text-xs tw:opacity-65">Quantity</dt>
            <dd class="tw:m-0 tw:font-serif tw:text-2xl tw:font-bold">{{ item.quantity }}</dd>
          </div>
        </dl>

        <DescriptionCollapse :description-html="item.descriptionHtml" title="Full description">
          <template #icon><i class="fa-solid fa-scroll" aria-hidden="true" /></template>
        </DescriptionCollapse>

        <form class="tw:grid tw:gap-2" @submit.prevent="updateQuantity">
          <label for="inventory-item-quantity" class="tw:text-sm tw:font-bold">Quantity</label>
          <div class="tw:flex tw:gap-2">
            <input
              id="inventory-item-quantity"
              v-model.number="quantityDraft"
              type="number"
              min="0"
              step="1"
              inputmode="numeric"
              class="tw:dui-input tw:min-h-11 tw:min-w-0 tw:flex-1"
              :disabled="isBusy"
            />
            <button
              type="submit"
              class="tw:dui-btn tw:dui-btn-primary tw:min-h-11"
              :disabled="isBusy || !quantityChanged"
            >
              Apply
            </button>
          </div>
        </form>

        <form class="tw:grid tw:gap-2" @submit.prevent="moveItem">
          <label for="inventory-container" class="tw:text-sm tw:font-bold">Stored in</label>
          <div class="tw:flex tw:gap-2">
            <select
              id="inventory-container"
              v-model="containerDraft"
              class="tw:dui-select tw:min-h-11 tw:min-w-0 tw:flex-1"
              :disabled="isBusy"
            >
              <option value="">Carried gear</option>
              <option
                v-for="container in containers.filter((entry) => entry.id !== item.id)"
                :key="container.id"
                :value="container.id"
              >
                {{ container.name }}
              </option>
            </select>
            <button
              type="submit"
              class="tw:dui-btn tw:min-h-11"
              :disabled="isBusy || containerDraft === item.containerId"
            >
              Move
            </button>
          </div>
        </form>

        <button
          v-if="item.canEquip"
          type="button"
          class="tw:dui-btn tw:min-h-11 tw:w-full"
          :class="item.equipped ? 'tw:dui-btn-outline' : 'tw:dui-btn-secondary'"
          :disabled="isBusy"
          @click="toggleEquipped"
        >
          <i
            :class="item.equipped ? 'fa-solid fa-box-archive' : 'fa-solid fa-hand-fist'"
            aria-hidden="true"
          />
          {{ item.equipped ? "Unequip" : "Equip" }}
        </button>
        <ConfirmAction
          :body="`Delete ${item.name} from this character? This cannot be undone.`"
          confirm-label="Delete item"
          title="Delete item?"
          trigger-label="Delete item"
          @confirm="deleteItem"
        />
      </div>
    </section>
  </article>
</template>
