<script setup lang="ts">
import { computed, ref, watch } from "vue";

import type { ActivationSettingsUserRow } from "../../../../types/activation-settings";

const props = defineProps<{
  saveEnabledUserIds: (userIds: string[]) => Promise<void>;
  users: ActivationSettingsUserRow[];
}>();

const checkedUserIds = ref(getInitialCheckedUserIds());
const isSaving = ref(false);
const saved = ref(false);
const hasUsers = computed(() => props.users.length > 0);

watch(
  () => props.users,
  () => {
    checkedUserIds.value = getInitialCheckedUserIds();
    saved.value = false;
  },
);

async function saveSettings(): Promise<void> {
  isSaving.value = true;

  try {
    await props.saveEnabledUserIds(checkedUserIds.value);
    saved.value = true;
  } finally {
    isSaving.value = false;
  }
}

function getInitialCheckedUserIds(): string[] {
  return props.users.filter((user) => user.enabled).map((user) => user.id);
}
</script>

<template>
  <main class="wfrp-on-the-go-settings">
    <header class="wfrp-on-the-go-settings__header">
      <p class="wfrp-on-the-go-settings__eyebrow">Drowsy's WFRP4e On The Go</p>
      <h1>Enabled Users</h1>
    </header>

    <form class="wfrp-on-the-go-settings__form" @submit.prevent="saveSettings">
      <div v-if="hasUsers" class="wfrp-on-the-go-settings__users">
        <label
          v-for="user in users"
          :key="user.id"
          class="wfrp-on-the-go-settings__user"
          :class="{ 'wfrp-on-the-go-settings__user--current': user.isCurrentUser }"
        >
          <input v-model="checkedUserIds" type="checkbox" :value="user.id" />
          <span>{{ user.name }}</span>
          <strong
            >{{ user.isGm ? "GM" : "Player" }}{{ user.isCurrentUser ? " · Current" : "" }}</strong
          >
        </label>
      </div>

      <p v-else class="wfrp-on-the-go-settings__empty">No Foundry users are available.</p>

      <footer class="wfrp-on-the-go-settings__actions">
        <p aria-live="polite">{{ saved ? "Saved" : "" }}</p>
        <button
          type="submit"
          class="tw:dui-btn tw:dui-btn-primary"
          :disabled="isSaving || !hasUsers"
        >
          {{ isSaving ? "Saving" : "Save" }}
        </button>
      </footer>
    </form>
  </main>
</template>
