<script setup lang="ts">
import { computed } from "vue";

import type {
  PlayerActions,
  PlayerCharacter,
  PlayerResource,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  character: PlayerCharacter;
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const resources = computed(() => [props.character.wounds, ...props.character.resources]);

function resourceValue(resource: PlayerResource): string {
  return resource.maximum === undefined
    ? String(resource.current)
    : `${resource.current} / ${resource.maximum}`;
}

function adjustResource(resource: PlayerResource, delta: number): void {
  void runPlayerAction(
    () => props.actions.adjustResource(resource.key, delta),
    `${resource.label} ${delta > 0 ? "increased" : "decreased"}.`,
  );
}

function rollCharacteristic(key: string, label: string): void {
  void runPlayerAction(() => props.actions.rollCharacteristic(key), `${label} test sent to chat.`);
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Status">
    <SectionHeading eyebrow="At the table" title="Status & Controls" />
    <p class="tw:m-0 tw:text-sm tw:opacity-70">
      Changes write to the character immediately and refresh every open mobile sheet.
    </p>

    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:dui-card tw:dui-card-border tw:bg-base-200 tw:shadow-md">
      <div class="tw:dui-card-body tw:gap-2 tw:p-3">
        <h3 class="tw:dui-card-title tw:font-serif">State controls</h3>
        <div class="tw:grid tw:gap-2 tw:min-[360px]:grid-cols-2">
          <article
            v-for="resource in resources"
            :key="resource.key"
            class="tw:grid tw:grid-cols-[minmax(0,1fr)_auto] tw:items-center tw:gap-2 tw:rounded-box tw:bg-base-300 tw:p-3"
          >
            <div class="tw:min-w-0">
              <span class="tw:block tw:text-xs tw:font-bold tw:opacity-65">{{
                resource.label
              }}</span>
              <strong class="tw:font-serif tw:text-xl tw:text-secondary tw:tabular-nums">
                {{ resourceValue(resource) }}
              </strong>
            </div>
            <div class="tw:dui-join">
              <button
                type="button"
                class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11"
                :disabled="isBusy || resource.current <= 0"
                :aria-label="`Decrease ${resource.label}`"
                @click="adjustResource(resource, -1)"
              >
                −
              </button>
              <button
                type="button"
                class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11"
                :disabled="
                  isBusy || (resource.maximum !== undefined && resource.current >= resource.maximum)
                "
                :aria-label="`Increase ${resource.label}`"
                @click="adjustResource(resource, 1)"
              >
                +
              </button>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="tw:dui-card tw:dui-card-border tw:bg-base-200 tw:shadow-md">
      <div class="tw:dui-card-body tw:gap-3 tw:p-3">
        <div class="tw:flex tw:items-center tw:justify-between tw:gap-2">
          <h3 class="tw:dui-card-title tw:font-serif">Characteristics</h3>
          <span class="tw:dui-badge tw:dui-badge-sm">Tap to test</span>
        </div>
        <div class="tw:grid tw:grid-cols-2 tw:gap-2 tw:min-[360px]:grid-cols-5">
          <button
            v-for="characteristic in character.characteristics"
            :key="characteristic.key"
            type="button"
            class="tw:dui-btn tw:dui-btn-ghost tw:grid tw:h-auto tw:min-h-20 tw:min-w-0 tw:place-items-center tw:gap-0 tw:border tw:border-secondary/30 tw:bg-base-300 tw:px-1 tw:py-2 tw:text-base-content"
            :disabled="isBusy"
            :aria-label="`Set up ${characteristic.label} test`"
            @click="rollCharacteristic(characteristic.key, characteristic.label)"
          >
            <span class="tw:text-xs tw:font-black tw:text-secondary">{{
              characteristic.abbreviation
            }}</span>
            <strong class="tw:font-serif tw:text-xl tw:tabular-nums">{{
              characteristic.value
            }}</strong>
            <small class="tw:text-[0.6rem] tw:opacity-65">Bonus {{ characteristic.bonus }}</small>
          </button>
        </div>
      </div>
    </section>

    <div class="tw:dui-stats tw:grid tw:grid-cols-3 tw:bg-base-200 tw:shadow-md">
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Move</div>
        <div class="tw:dui-stat-value tw:text-xl">{{ character.movement.move }}</div>
      </div>
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Walk</div>
        <div class="tw:dui-stat-value tw:text-xl">{{ character.movement.walk }}</div>
      </div>
      <div class="tw:dui-stat tw:min-w-0 tw:p-3">
        <div class="tw:dui-stat-title">Run</div>
        <div class="tw:dui-stat-value tw:text-xl">{{ character.movement.run }}</div>
      </div>
    </div>
  </section>
</template>
