export function asRecord(value: unknown): Record<string, unknown> | undefined {
  return typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)
    : undefined;
}

export function readString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

export function readNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

export function readBoolean(value: unknown): boolean {
  return value === true;
}

// WFRP 10 exposes deprecated `worn` getters. Read them only for older models without equipped.
export function readEquipped(system: Record<string, unknown>): boolean {
  const equipped = system["equipped"];
  if (typeof equipped === "boolean") return equipped;

  const value = asRecord(equipped)?.["value"];
  if (typeof value === "boolean") return value;

  const worn = system["worn"];
  return readBoolean(worn) || readBoolean(asRecord(worn)?.["value"]);
}

export function readArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

export function readEnabledKeys(value: unknown): string[] {
  const record = asRecord(value);
  return record
    ? Object.entries(record)
        .filter(([, enabled]) => readBoolean(enabled))
        .map(([key]) => key)
    : [];
}

export function readNumeric(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value !== "string" || !value.trim()) {
    return undefined;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

export function readNestedString(
  record: Record<string, unknown> | undefined,
  parentKey: string,
  key: string,
): string {
  return readString(asRecord(record?.[parentKey])?.[key]);
}

export function readNestedNumber(
  record: Record<string, unknown> | undefined,
  parentKey: string,
  key: string,
): number | undefined {
  return readNumber(asRecord(record?.[parentKey])?.[key]);
}

export function readNestedNumeric(
  record: Record<string, unknown> | undefined,
  parentKey: string,
  key: string,
): number | undefined {
  return readNumeric(asRecord(record?.[parentKey])?.[key]);
}

export function readNestedBoolean(
  record: Record<string, unknown> | undefined,
  parentKey: string,
  key: string,
): boolean {
  return asRecord(record?.[parentKey])?.[key] === true;
}

export function readDescription(record: Record<string, unknown> | undefined): string {
  return readNestedString(record, "description", "value");
}
