<script setup lang="ts">
import { reactive, watch } from "vue";

import type {
  PlayerActions,
  PlayerCharacter,
  PlayerNotesUpdate,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  character: PlayerCharacter;
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const draft = reactive<PlayerNotesUpdate>({ ...props.character.notes });

watch(
  () => props.character.notes,
  (notes) => Object.assign(draft, notes),
  { deep: true },
);

function save(): void {
  void runPlayerAction(() => props.actions.updateNotes({ ...draft }), "Character notes saved.");
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Notes and character record">
    <SectionHeading eyebrow="Your story" title="Notes & Record" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:dui-card tw:dui-card-border tw:bg-base-200">
      <div class="tw:dui-card-body tw:gap-3 tw:p-4">
        <h3 class="tw:dui-card-title tw:font-serif">Personal details</h3>
        <dl class="tw:m-0 tw:grid tw:grid-cols-2 tw:gap-2">
          <div
            v-for="detail in character.personalDetails"
            :key="detail.key"
            class="tw:rounded-field tw:bg-base-300 tw:p-2"
          >
            <dt class="tw:text-xs tw:opacity-60">{{ detail.label }}</dt>
            <dd class="tw:m-0 tw:font-bold tw:[overflow-wrap:anywhere]">
              {{ detail.value || "—" }}
            </dd>
          </div>
        </dl>
      </div>
    </section>

    <form class="tw:grid tw:gap-4" @submit.prevent="save">
      <section class="tw:dui-card tw:dui-card-border tw:bg-base-200">
        <div class="tw:dui-card-body tw:gap-3 tw:p-4">
          <h3 class="tw:dui-card-title tw:font-serif">Biography & Motivation</h3>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold">
            Motivation
            <input v-model="draft.motivation" class="tw:dui-input tw:min-h-11 tw:w-full" />
          </label>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold">
            Biography
            <textarea v-model="draft.biography" rows="8" class="tw:dui-textarea tw:w-full" />
          </label>
        </div>
      </section>

      <section class="tw:dui-card tw:dui-card-border tw:bg-base-200">
        <div class="tw:dui-card-body tw:gap-3 tw:p-4">
          <h3 class="tw:dui-card-title tw:font-serif">Personal ambitions</h3>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold"
            >Short term<textarea
              v-model="draft.personalShortTermAmbition"
              rows="3"
              class="tw:dui-textarea tw:w-full"
            />
          </label>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold"
            >Long term<textarea
              v-model="draft.personalLongTermAmbition"
              rows="3"
              class="tw:dui-textarea tw:w-full"
            />
          </label>
        </div>
      </section>

      <section class="tw:dui-card tw:dui-card-border tw:bg-base-200">
        <div class="tw:dui-card-body tw:gap-3 tw:p-4">
          <h3 class="tw:dui-card-title tw:font-serif">Party ambitions</h3>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold"
            >Party name<input v-model="draft.partyName" class="tw:dui-input tw:min-h-11 tw:w-full"
          /></label>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold"
            >Short term<textarea
              v-model="draft.partyShortTermAmbition"
              rows="3"
              class="tw:dui-textarea tw:w-full"
            />
          </label>
          <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold"
            >Long term<textarea
              v-model="draft.partyLongTermAmbition"
              rows="3"
              class="tw:dui-textarea tw:w-full"
            />
          </label>
        </div>
      </section>

      <button
        type="submit"
        class="tw:dui-btn tw:dui-btn-primary tw:min-h-12 tw:w-full"
        :disabled="isBusy"
      >
        <i class="fa-solid fa-floppy-disk" aria-hidden="true" />
        {{ isBusy ? "Saving…" : "Save notes" }}
      </button>
    </form>
  </section>
</template>
