<script setup lang="ts">
import { computed } from "vue";

import type {
  PlayerActions,
  PlayerCharacter,
  PlayerWeapon,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  character: PlayerCharacter;
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const advantage = computed(() =>
  props.character.resources.find((resource) => resource.key === "advantage"),
);

function adjust(key: string, delta: number): void {
  void runPlayerAction(() => props.actions.adjustResource(key, delta), "Combat state updated.");
}

function rollWeapon(weapon: PlayerWeapon): void {
  void runPlayerAction(
    () => props.actions.rollWeapon(weapon.id),
    `${weapon.name} test sent to chat.`,
  );
}

function reload(weapon: PlayerWeapon): void {
  void runPlayerAction(
    () => props.actions.reloadWeapon(weapon.id),
    `${weapon.name} reload updated.`,
  );
}
</script>

<template>
  <section class="tw:grid tw:gap-4 tw:p-3" aria-label="Combat">
    <SectionHeading eyebrow="At the ready" title="Combat" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section class="tw:grid tw:grid-cols-2 tw:gap-2" aria-label="Combat state">
      <article class="tw:rounded-box tw:bg-base-200 tw:p-3 tw:shadow-md">
        <span class="tw:text-xs tw:font-bold tw:opacity-65">Wounds</span>
        <strong class="tw:block tw:font-serif tw:text-xl tw:tabular-nums">
          {{ character.wounds.current }} / {{ character.wounds.maximum }}
        </strong>
        <div class="tw:dui-join tw:mt-2 tw:w-full">
          <button
            class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11 tw:flex-1"
            :disabled="isBusy"
            @click="adjust('wounds', -1)"
          >
            −
          </button>
          <button
            class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11 tw:flex-1"
            :disabled="isBusy"
            @click="adjust('wounds', 1)"
          >
            +
          </button>
        </div>
      </article>
      <article class="tw:rounded-box tw:bg-base-200 tw:p-3 tw:shadow-md">
        <span class="tw:text-xs tw:font-bold tw:opacity-65">Advantage</span>
        <strong class="tw:block tw:font-serif tw:text-xl tw:tabular-nums">{{
          advantage?.current ?? 0
        }}</strong>
        <div class="tw:dui-join tw:mt-2 tw:w-full">
          <button
            class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11 tw:flex-1"
            :disabled="isBusy"
            @click="adjust('advantage', -1)"
          >
            −
          </button>
          <button
            class="tw:dui-btn tw:dui-btn-sm tw:dui-join-item tw:min-h-11 tw:flex-1"
            :disabled="isBusy"
            @click="adjust('advantage', 1)"
          >
            +
          </button>
        </div>
      </article>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="weapons-heading">
      <div class="tw:flex tw:items-center tw:justify-between">
        <h3 id="weapons-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">Weapons</h3>
        <span class="tw:dui-badge tw:dui-badge-sm">{{ character.combat.weapons.length }}</span>
      </div>
      <DescriptionCollapse
        v-for="weapon in character.combat.weapons"
        :key="weapon.id"
        :description-html="weapon.descriptionHtml"
        :image-url="weapon.imageUrl"
        :subtitle="
          [
            weapon.damage && `Damage ${weapon.damage}`,
            weapon.range && `Range ${weapon.range}`,
            weapon.reach && `Reach ${weapon.reach}`,
          ]
            .filter(Boolean)
            .join(' · ')
        "
        :title="weapon.name"
      >
        <template #badge>
          <span
            v-if="weapon.equipped"
            class="tw:dui-badge tw:dui-badge-secondary tw:dui-badge-sm"
            title="Equipped"
            aria-label="Equipped"
          >
            <i class="fa-solid fa-check" aria-hidden="true" />
          </span>
        </template>
        <dl class="tw:m-0 tw:grid tw:grid-cols-2 tw:gap-2 tw:text-sm">
          <div v-if="weapon.ammunitionName">
            <dt class="tw:opacity-60">Ammunition</dt>
            <dd class="tw:m-0 tw:font-bold">{{ weapon.ammunitionName }}</dd>
          </div>
          <div v-if="weapon.range">
            <dt class="tw:opacity-60">Loaded</dt>
            <dd class="tw:m-0 tw:font-bold">{{ weapon.loaded ? "Yes" : "No" }}</dd>
          </div>
          <div v-if="weapon.qualities.length">
            <dt class="tw:opacity-60">Qualities</dt>
            <dd class="tw:m-0">{{ weapon.qualities.join(", ") }}</dd>
          </div>
          <div v-if="weapon.flaws.length">
            <dt class="tw:opacity-60">Flaws</dt>
            <dd class="tw:m-0">{{ weapon.flaws.join(", ") }}</dd>
          </div>
        </dl>
        <p v-if="weapon.special" class="tw:m-0 tw:text-sm">
          <strong>Special:</strong> {{ weapon.special }}
        </p>
        <div class="tw:grid tw:gap-2 tw:min-[360px]:grid-cols-2">
          <button
            type="button"
            class="tw:dui-btn tw:dui-btn-primary tw:min-h-11"
            :disabled="isBusy"
            @click="rollWeapon(weapon)"
          >
            <i class="fa-solid fa-dice-d20" aria-hidden="true" /> Set up attack
          </button>
          <button
            v-if="weapon.range"
            type="button"
            class="tw:dui-btn tw:min-h-11"
            :disabled="isBusy"
            @click="reload(weapon)"
          >
            <i class="fa-solid fa-rotate" aria-hidden="true" /> Reload
          </button>
        </div>
      </DescriptionCollapse>
      <p v-if="character.combat.weapons.length === 0" class="tw:m-0 tw:text-sm tw:opacity-65">
        No weapons recorded.
      </p>
    </section>

    <section class="tw:grid tw:gap-2" aria-labelledby="armour-heading">
      <h3 id="armour-heading" class="tw:m-0 tw:font-serif tw:text-lg tw:font-bold">
        Armour by location
      </h3>
      <div class="tw:grid tw:grid-cols-3 tw:gap-2">
        <div
          v-for="location in character.combat.armourByLocation"
          :key="location.key"
          class="tw:rounded-field tw:bg-base-300 tw:p-2 tw:text-center"
        >
          <small class="tw:block tw:opacity-65">{{ location.label }}</small>
          <strong class="tw:font-serif tw:text-xl tw:text-secondary">{{
            location.armourPoints
          }}</strong>
        </div>
      </div>
      <DescriptionCollapse
        v-for="armour in character.combat.armour"
        :key="armour.id"
        :description-html="armour.descriptionHtml"
        :image-url="armour.imageUrl"
        :subtitle="
          armour.locations
            .map((location) => `${location.label} ${location.armourPoints}`)
            .join(' · ')
        "
        :title="armour.name"
      >
        <template #badge>
          <span v-if="armour.worn" class="tw:dui-badge tw:dui-badge-secondary tw:dui-badge-sm"
            >Worn</span
          >
        </template>
        <p v-if="armour.qualities.length" class="tw:m-0 tw:text-sm">
          <strong>Qualities:</strong> {{ armour.qualities.join(", ") }}
        </p>
        <p v-if="armour.flaws.length" class="tw:m-0 tw:text-sm">
          <strong>Flaws:</strong> {{ armour.flaws.join(", ") }}
        </p>
      </DescriptionCollapse>
    </section>
  </section>
</template>
