<script setup lang="ts">
import { computed, ref, watch } from "vue";

import type { MobileJournalEntry } from "../../../../types/mobile-journal";
import type { JournalTab } from "./types";

import MobileJournalFolderTree from "./MobileJournalFolderTree.vue";

const props = defineProps<{
  journalCount: number;
  searchText: string;
  tabs: JournalTab[];
  totalPageCount: number;
}>();

const emit = defineEmits<{
  "openEntry": [entry: MobileJournalEntry];
  "update:searchText": [value: string];
}>();

const activeTabId = ref(props.tabs[0]?.id ?? "");
const hasSearchQuery = computed(() => props.searchText.trim().length > 0);

const activeTab = computed(() => {
  return props.tabs.find((tab) => tab.id === activeTabId.value) ?? props.tabs[0];
});

watch(
  () => props.tabs.map((tab) => tab.id),
  () => {
    if (!props.tabs.some((tab) => tab.id === activeTabId.value)) {
      activeTabId.value = props.tabs[0]?.id ?? "";
    }
  },
);

function selectTab(tabId: string): void {
  activeTabId.value = tabId;
}

function updateSearch(event: Event): void {
  const input = event.target;

  if (input instanceof HTMLInputElement) {
    emit("update:searchText", input.value);
  }
}
</script>

<template>
  <section class="mobile-journal-shell__list-view">
    <label class="mobile-journal-shell__search">
      <span>Search Journals</span>
      <input
        :value="searchText"
        type="search"
        autocomplete="off"
        class="tw:dui-input"
        @input="updateSearch"
      />
    </label>

    <div class="mobile-journal-shell__list-summary">
      <span>{{ journalCount }} journals</span>
      <span>{{ totalPageCount }} pages</span>
    </div>

    <nav class="mobile-journal-shell__tabs" aria-label="Journal collections">
      <button
        v-for="tab in tabs"
        :key="tab.id"
        type="button"
        class="mobile-journal-shell__tab-button"
        :aria-selected="activeTab?.id === tab.id"
        @click="selectTab(tab.id)"
      >
        <strong>{{ tab.label }}</strong>
        <small>{{ tab.journalCount }}</small>
      </button>
    </nav>

    <section v-if="activeTab" class="mobile-journal-shell__tab-panel">
      <header class="mobile-journal-shell__tab-header">
        <strong>{{ activeTab.label }}</strong>
        <small>{{ activeTab.journalCount }} journals / {{ activeTab.pageCount }} pages</small>
      </header>

      <MobileJournalFolderTree
        v-if="activeTab.folders.length > 0"
        :key="activeTab.id"
        :depth="0"
        :folders="activeTab.folders"
        :has-search-query="hasSearchQuery"
        @open-entry="emit('openEntry', $event)"
      />

      <section v-else class="mobile-journal-shell__empty">
        <h2>No Journals</h2>
      </section>
    </section>
  </section>
</template>
