import type { PlayerNotesUpdate } from "../../../types/player-character";
import { getCurrentCharacterActor } from "./data";

export async function updateCurrentPlayerNotes(notes: PlayerNotesUpdate): Promise<void> {
  await getCurrentCharacterActor().update({
    "system.details.biography.value": notes.biography,
    "system.details.motivation.value": notes.motivation,
    "system.details.party-ambitions.long-term": notes.partyLongTermAmbition,
    "system.details.party-ambitions.name": notes.partyName,
    "system.details.party-ambitions.short-term": notes.partyShortTermAmbition,
    "system.details.personal-ambitions.long-term": notes.personalLongTermAmbition,
    "system.details.personal-ambitions.short-term": notes.personalShortTermAmbition,
  });
}
