<script setup lang="ts">
import type { PlayerActions, PlayerPrayer } from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  god: string;
  prayers: PlayerPrayer[];
}>();

const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();

function pray(prayer: PlayerPrayer): void {
  void runPlayerAction(
    () => props.actions.rollPrayer(prayer.id),
    `${prayer.name} result sent to chat.`,
  );
}
</script>

<template>
  <section class="tw:grid tw:gap-3 tw:p-3" aria-label="Religion">
    <SectionHeading :count="prayers.length" eyebrow="Faith and favour" title="Religion" />
    <div v-if="god" class="tw:dui-alert tw:items-center" role="status">
      <i class="fa-solid fa-place-of-worship" aria-hidden="true" />
      <span><strong>Deity:</strong> {{ god }}</span>
    </div>
    <ActionStatus :message="actionMessage" :tone="actionTone" />
    <div class="tw:grid tw:gap-2">
      <DescriptionCollapse
        v-for="prayer in prayers"
        :key="prayer.id"
        :description-html="prayer.descriptionHtml"
        :image-url="prayer.imageUrl"
        :subtitle="[prayer.god || god, prayer.type].filter(Boolean).join(' · ')"
        :title="prayer.name"
      >
        <dl class="tw:m-0 tw:grid tw:grid-cols-2 tw:gap-2 tw:text-sm">
          <div v-if="prayer.range">
            <dt class="tw:opacity-60">Range</dt>
            <dd class="tw:m-0 tw:font-bold">{{ prayer.range }}</dd>
          </div>
          <div v-if="prayer.target">
            <dt class="tw:opacity-60">Target</dt>
            <dd class="tw:m-0 tw:font-bold">{{ prayer.target }}</dd>
          </div>
          <div v-if="prayer.duration">
            <dt class="tw:opacity-60">Duration</dt>
            <dd class="tw:m-0 tw:font-bold">{{ prayer.duration }}</dd>
          </div>
          <div v-if="prayer.damage">
            <dt class="tw:opacity-60">Damage</dt>
            <dd class="tw:m-0 tw:font-bold">{{ prayer.damage }}</dd>
          </div>
        </dl>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-primary tw:min-h-11 tw:w-full"
          :disabled="isBusy"
          @click="pray(prayer)"
        >
          <i class="fa-solid fa-hands-praying" aria-hidden="true" /> Set up prayer test
        </button>
      </DescriptionCollapse>
    </div>
    <div v-if="prayers.length === 0" class="tw:dui-alert tw:items-start" role="status">
      <i class="fa-solid fa-hands-praying tw:mt-1" aria-hidden="true" />
      <span>No prayers or blessings are recorded on this character.</span>
    </div>
  </section>
</template>
