import type {
  PlayerInventory,
  PlayerInventoryItem,
  PlayerInventoryItemType,
} from "../../types/player-character";
import { classifyInventoryItem, compareInventoryItems } from "../functions/player-sheet/inventory";
import {
  asRecord,
  readDescription,
  readEquipped,
  readNestedNumeric,
  readNestedString,
  readNumeric,
  readString,
} from "./value-readers";

const INVENTORY_ITEM_TYPES = new Set([
  "ammunition",
  "armour",
  "container",
  "money",
  "trapping",
  "weapon",
]);

export function extractPlayerInventory(
  status: Record<string, unknown>,
  items: unknown[],
): PlayerInventory {
  const encumbrance = asRecord(status["encumbrance"]);
  const inventoryItems = items
    .map(extractInventoryItem)
    .filter((item): item is PlayerInventoryItem => item !== undefined)
    .sort(compareInventoryItems);

  return {
    currentEncumbrance: readNumeric(encumbrance?.["current"]) ?? 0,
    items: inventoryItems,
    maximumEncumbrance: readNumeric(encumbrance?.["max"]) ?? 0,
  };
}

export async function updateCurrentPlayerInventoryQuantity(
  itemId: string,
  quantity: number,
): Promise<void> {
  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new Error("Quantity must be a whole number of zero or more.");
  }

  const item = getCurrentPlayerInventoryItem(itemId);
  await item.update({ "system.quantity.value": quantity });
}

export async function toggleCurrentPlayerInventoryEquipped(itemId: string): Promise<void> {
  const item = getCurrentPlayerInventoryItem(itemId);
  const system = asRecord(item.system);
  const toggleEquip = system?.["toggleEquip"];

  if (typeof toggleEquip !== "function") {
    throw new Error(`${item.name} cannot be equipped.`);
  }

  await toggleEquip.call(item.system);
}

function extractInventoryItem(item: unknown): PlayerInventoryItem | undefined {
  const rawItem = asRecord(item);
  const type = readString(rawItem?.["type"]);

  if (!rawItem || !isInventoryItemType(type)) {
    return undefined;
  }

  const id = readString(rawItem["id"]) || readString(rawItem["_id"]);
  const name = readString(rawItem["name"]);
  const system = asRecord(rawItem["system"]);

  if (!id || !name || !system) {
    return undefined;
  }

  const quantity = Math.max(0, Math.floor(readNestedNumeric(system, "quantity", "value") ?? 1));
  const unitEncumbrance = readNestedNumeric(system, "encumbrance", "value") ?? 0;
  const { category, group } = classifyInventoryItem(
    type,
    readNestedString(system, "trappingType", "value"),
  );

  return {
    canEquip: typeof system["toggleEquip"] === "function",
    category,
    containerId: readNestedString(system, "location", "value"),
    descriptionHtml: readDescription(system),
    encumbrance: readNestedNumeric(system, "encumbrance", "total") ?? unitEncumbrance * quantity,
    equipped: readEquipped(system),
    group,
    id,
    imageUrl: readString(rawItem["img"]),
    name,
    quantity,
    type,
  };
}

function isInventoryItemType(type: string): type is PlayerInventoryItemType {
  return INVENTORY_ITEM_TYPES.has(type);
}

function getCurrentPlayerInventoryItem(itemId: string): FoundryItem {
  const actor = game.user.character;

  if (!actor || actor.type !== "character") {
    throw new Error("No supported player character is assigned.");
  }

  const item = getActorItems(actor.items).find((candidate) => {
    const rawItem = asRecord(candidate);
    return readString(rawItem?.["id"]) === itemId;
  });

  if (!isFoundryInventoryItem(item)) {
    throw new Error("That inventory item is no longer available.");
  }

  return item;
}

function getActorItems(items: FoundryCollection): unknown[] {
  return Array.isArray(items.contents) ? items.contents : [];
}

function isFoundryInventoryItem(item: unknown): item is FoundryItem {
  const rawItem = asRecord(item);

  return (
    rawItem !== undefined &&
    INVENTORY_ITEM_TYPES.has(readString(rawItem["type"])) &&
    typeof rawItem["update"] === "function"
  );
}
