import type {
  ActivationSettingsUserRow,
  MobileActivationSettings,
  MobileUiMode,
} from "../../../types/activation-settings";

import { PACKAGE_ID } from "../../constants";

const ACTIVATION_SETTINGS_VERSION = 1;
const ACTIVATION_SETTINGS_VERSION_SETTING = "activationSettingsVersion";
const ENABLED_USER_IDS_SETTING = "enabledUserIds";
const LEGACY_ENABLED_GM_USER_IDS_SETTING = "enabledGmUserIds";
const FORCE_MOBILE_UI_SETTING = "forceMobileUi";
const MOBILE_WIDTH_THRESHOLD_SETTING = "mobileWidthThreshold";
const DEFAULT_MOBILE_WIDTH_THRESHOLD = 800;

export function registerActivationSettings(): void {
  registerHiddenWorldSetting(ENABLED_USER_IDS_SETTING, []);
  registerHiddenWorldSetting(LEGACY_ENABLED_GM_USER_IDS_SETTING, []);
  registerHiddenWorldSetting(ACTIVATION_SETTINGS_VERSION_SETTING, 0);

  game.settings.register(PACKAGE_ID, MOBILE_WIDTH_THRESHOLD_SETTING, {
    name: "WFRP_ON_THE_GO.settings.mobileWidthThreshold.name",
    hint: "WFRP_ON_THE_GO.settings.mobileWidthThreshold.hint",
    scope: "world",
    config: true,
    restricted: true,
    default: DEFAULT_MOBILE_WIDTH_THRESHOLD,
    type: Number,
    range: {
      min: 320,
      max: 1400,
      step: 10,
    },
  });

  game.settings.register(PACKAGE_ID, FORCE_MOBILE_UI_SETTING, {
    name: "WFRP_ON_THE_GO.settings.forceMobileUi.name",
    hint: "WFRP_ON_THE_GO.settings.forceMobileUi.hint",
    scope: "client",
    config: true,
    default: false,
    type: Boolean,
  });
}

export async function migrateActivationSettings(): Promise<void> {
  if (!game.user.isGM || getActivationSettingsVersion() >= ACTIVATION_SETTINGS_VERSION) {
    return;
  }

  const enabledUserIds = getStoredUserIds(ENABLED_USER_IDS_SETTING);
  const legacyEnabledGmUserIds = getStoredUserIds(LEGACY_ENABLED_GM_USER_IDS_SETTING);
  const migratedUserIds = enabledUserIds.length > 0 ? enabledUserIds : legacyEnabledGmUserIds;

  await setEnabledUserIds(migratedUserIds);
  await game.settings.set(
    PACKAGE_ID,
    ACTIVATION_SETTINGS_VERSION_SETTING,
    ACTIVATION_SETTINGS_VERSION,
  );
}

export function getActivationSettingsUserRows(): ActivationSettingsUserRow[] {
  const enabledUserIds = new Set(getEnabledUserIds());

  return getUsers().map((user) => ({
    enabled: enabledUserIds.has(user.id),
    id: user.id,
    isCurrentUser: user.id === game.user.id,
    isGm: user.isGM,
    name: user.name,
  }));
}

export function getMobileActivationSettings(): MobileActivationSettings {
  return {
    forceMobileUi: getForceMobileUi(),
    mobileWidthThreshold: getMobileWidthThreshold(),
    users: getActivationSettingsUserRows(),
  };
}

export async function setEnabledUserIds(userIds: string[]): Promise<void> {
  const existingUserIds = new Set(getUsers().map((user) => user.id));
  const uniqueUserIds = Array.from(new Set(userIds));
  const nextUserIds = uniqueUserIds.filter((userId) => existingUserIds.has(userId));

  await game.settings.set(PACKAGE_ID, ENABLED_USER_IDS_SETTING, nextUserIds);
}

export async function saveMobileActivationSettings(
  settings: MobileActivationSettings,
): Promise<void> {
  const enabledUserIds = settings.users.filter((user) => user.enabled).map((user) => user.id);

  await setEnabledUserIds(enabledUserIds);
  await game.settings.set(
    PACKAGE_ID,
    MOBILE_WIDTH_THRESHOLD_SETTING,
    clampMobileWidthThreshold(settings.mobileWidthThreshold),
  );
  await game.settings.set(PACKAGE_ID, FORCE_MOBILE_UI_SETTING, settings.forceMobileUi);
}

export async function setForceMobileUi(forceMobileUi: boolean): Promise<void> {
  await game.settings.set(PACKAGE_ID, FORCE_MOBILE_UI_SETTING, forceMobileUi);
}

export function getMobileUiMode(viewportWidth = window.innerWidth): MobileUiMode {
  const currentUserIsEnabled = getEnabledUserIds().includes(game.user.id);
  const viewportMatches = getForceMobileUi() || viewportWidth <= getMobileWidthThreshold();

  if (!currentUserIsEnabled || !viewportMatches) {
    return "none";
  }

  return game.user.isGM ? "gm" : "player";
}

function registerHiddenWorldSetting(key: string, defaultValue: unknown): void {
  game.settings.register(PACKAGE_ID, key, {
    name: key,
    hint: key,
    scope: "world",
    config: false,
    restricted: true,
    default: defaultValue,
    type: typeof defaultValue === "number" ? Number : Object,
  });
}

function getActivationSettingsVersion(): number {
  const rawValue = game.settings.get(PACKAGE_ID, ACTIVATION_SETTINGS_VERSION_SETTING);

  return typeof rawValue === "number" && Number.isFinite(rawValue) ? rawValue : 0;
}

function getEnabledUserIds(): string[] {
  return getStoredUserIds(ENABLED_USER_IDS_SETTING);
}

function getStoredUserIds(settingKey: string): string[] {
  const rawValue = game.settings.get(PACKAGE_ID, settingKey);

  if (!Array.isArray(rawValue)) {
    return [];
  }

  return rawValue.filter((userId): userId is string => typeof userId === "string");
}

function getForceMobileUi(): boolean {
  return game.settings.get(PACKAGE_ID, FORCE_MOBILE_UI_SETTING) === true;
}

function getMobileWidthThreshold(): number {
  const rawValue = game.settings.get(PACKAGE_ID, MOBILE_WIDTH_THRESHOLD_SETTING);

  if (typeof rawValue !== "number" || !Number.isFinite(rawValue)) {
    return DEFAULT_MOBILE_WIDTH_THRESHOLD;
  }

  return rawValue;
}

function clampMobileWidthThreshold(value: number): number {
  if (!Number.isFinite(value)) {
    return DEFAULT_MOBILE_WIDTH_THRESHOLD;
  }

  return Math.min(1400, Math.max(320, Math.round(value)));
}

function getUsers(): FoundryUser[] {
  return game.users.filter(() => true);
}
