<script setup lang="ts">
import { computed } from "vue";

import { usePlayerSheetStore } from "../../state/player-sheet-store";
import type { PlayerCharacter } from "../../../../../types/player-character";

const props = defineProps<{
  character: PlayerCharacter;
}>();

const store = usePlayerSheetStore();
const full = computed(() => store.activeDestination === "status");
const woundPercentage = computed(() => {
  const maximum = props.character.wounds.maximum ?? 0;
  return maximum > 0
    ? Math.max(0, Math.min(100, (props.character.wounds.current / maximum) * 100))
    : 0;
});
</script>

<template>
  <section
    v-if="full"
    class="tw:grid tw:grid-cols-[auto_minmax(0,1fr)] tw:gap-3 tw:border-b tw:border-base-300 tw:bg-linear-to-br tw:from-base-200 tw:to-base-100 tw:p-4 tw:shadow-inner"
    aria-labelledby="character-name"
  >
    <div class="tw:dui-avatar">
      <div
        class="tw:h-[5.4rem] tw:w-[4.6rem] tw:overflow-hidden tw:rounded-field tw:border-2 tw:border-secondary tw:bg-neutral tw:ring-3 tw:ring-base-100"
      >
        <img
          :src="character.imageUrl"
          :alt="`${character.name} portrait`"
          width="92"
          height="108"
          class="tw:h-full tw:w-full tw:object-cover"
        />
      </div>
    </div>
    <div class="tw:grid tw:min-w-0 tw:content-center">
      <p class="tw:m-0 tw:text-xs tw:font-extrabold tw:text-secondary tw:uppercase">
        {{ character.species || "Unknown species" }}
      </p>
      <h1
        id="character-name"
        class="tw:my-1 tw:font-serif tw:text-2xl tw:leading-none tw:font-bold"
      >
        {{ character.name }}
      </h1>
      <span class="tw:text-sm tw:opacity-75">{{ character.career.name }}</span>
    </div>
    <div class="tw:col-span-full tw:grid tw:gap-1">
      <div class="tw:flex tw:items-baseline tw:justify-between">
        <span class="tw:text-xs tw:font-extrabold tw:uppercase">Wounds</span>
        <strong class="tw:font-serif tw:text-lg tw:tabular-nums">
          {{ character.wounds.current }} / {{ character.wounds.maximum }}
        </strong>
      </div>
      <progress
        class="tw:dui-progress tw:dui-progress-error"
        :value="woundPercentage"
        max="100"
        aria-label="Current wounds"
      />
    </div>
  </section>

  <section
    v-else
    class="tw:grid tw:grid-cols-[auto_minmax(0,1fr)_auto] tw:items-center tw:gap-3 tw:border-b tw:border-base-300 tw:bg-base-200 tw:px-3 tw:py-2 tw:shadow-inner"
    aria-label="Current character"
  >
    <div class="tw:dui-avatar">
      <div class="tw:size-10 tw:overflow-hidden tw:rounded-field tw:border tw:border-secondary">
        <img
          :src="character.imageUrl"
          alt=""
          width="40"
          height="40"
          class="tw:h-full tw:w-full tw:object-cover"
        />
      </div>
    </div>
    <div class="tw:min-w-0">
      <strong class="tw:block tw:truncate tw:font-serif">{{ character.name }}</strong>
      <small class="tw:block tw:truncate tw:opacity-65">{{ character.career.name }}</small>
    </div>
    <div class="tw:text-right">
      <span class="tw:block tw:text-[0.6rem] tw:font-black tw:uppercase">Wounds</span>
      <strong class="tw:font-serif tw:tabular-nums">
        {{ character.wounds.current }} / {{ character.wounds.maximum }}
      </strong>
    </div>
  </section>
</template>
