export function adjustResourceValue(current: number, delta: number, maximum?: number): number {
  if (
    ![current, delta].every(Number.isFinite) ||
    (maximum !== undefined && !Number.isFinite(maximum))
  ) {
    throw new Error("The resource values are invalid.");
  }

  const upperBound = maximum ?? Number.POSITIVE_INFINITY;
  return Math.max(0, Math.min(upperBound, current + delta));
}
