<script setup lang="ts">
import { computed } from "vue";

import { usePlayerSheetStore } from "../state/player-sheet-store";
import type { MobileJournalEntry } from "../../../../types/mobile-journal";
import type {
  PlayerActions,
  PlayerActivityMessage,
  PlayerCharacterState,
} from "../../../../types/player-character";
import CharacterBanner from "./chrome/CharacterBanner.vue";
import ShellHeader from "./chrome/ShellHeader.vue";
import AdventureMenu from "./navigation/AdventureMenu.vue";
import PlayerContent from "./PlayerContent.vue";
import PlayerSheetStateAlert from "./PlayerSheetStateAlert.vue";

const props = defineProps<{
  actions: PlayerActions;
  activity: PlayerActivityMessage[];
  characterState: PlayerCharacterState;
  journalError?: string | undefined;
  journals: MobileJournalEntry[];
}>();

const store = usePlayerSheetStore();
const character = computed(() =>
  props.characterState.status === "ready" ? props.characterState.character : undefined,
);
</script>

<template>
  <div
    class="tw:dui-drawer tw:mx-auto tw:h-full tw:min-h-0 tw:w-full tw:max-w-[430px] tw:overflow-hidden tw:[&_*]:box-border tw:[&_*::after]:box-border tw:[&_*::before]:box-border"
  >
    <input
      id="player-adventure-menu"
      v-model="store.menuOpen"
      type="checkbox"
      class="tw:dui-drawer-toggle"
      :disabled="!character"
      aria-label="Open adventure menu"
    />
    <div class="tw:dui-drawer-content tw:min-h-0">
      <main
        class="tw:flex tw:h-full tw:min-h-0 tw:w-full tw:flex-col tw:overflow-hidden tw:border-x tw:border-base-300 tw:bg-base-100 tw:text-base-content tw:shadow-2xl"
      >
        <ShellHeader :character-state="characterState" />
        <PlayerSheetStateAlert
          v-if="characterState.status !== 'ready'"
          :character-state="characterState"
        />
        <template v-else-if="character">
          <CharacterBanner :character="character" />
          <PlayerContent
            :actions="actions"
            :activity="activity"
            :character="character"
            :journal-error="journalError"
            :journals="journals"
          />
        </template>
      </main>
    </div>
    <div v-if="character" id="player-adventure-menu-panel" class="tw:dui-drawer-side tw:z-50">
      <label
        for="player-adventure-menu"
        class="tw:dui-drawer-overlay"
        aria-label="Close adventure menu"
      />
      <AdventureMenu :character="character" />
    </div>
  </div>
</template>
