<script setup lang="ts">
import { computed, ref } from "vue";

import type { MobileJournalEntry } from "../../../../types/mobile-journal";
import type { JournalFolder, JournalTab } from "./types";

import MobileJournalList from "./MobileJournalList.vue";
import MobileJournalReader from "./MobileJournalReader.vue";

const props = defineProps<{
  journals: MobileJournalEntry[];
}>();

const COMPENDIUMS_TAB_ID = "compendiums";
const NO_FOLDER_NAME = "No Folder";
const WORLD_ROOT_FOLDER_NAME = "World";
const WORLD_TAB_ID = "world";

const isReading = ref(false);
const searchText = ref("");
const selectedEntryId = ref("");
const selectedPageId = ref("");

const filteredJournals = computed(() => {
  const query = searchText.value.trim().toLocaleLowerCase();

  if (!query) {
    return props.journals;
  }

  return props.journals.filter((journal) => {
    const pageMatches = journal.pages.some((page) => {
      return page.name.toLocaleLowerCase().includes(query);
    });

    return (
      journal.name.toLocaleLowerCase().includes(query) ||
      journal.folderName?.toLocaleLowerCase().includes(query) ||
      journal.source.label.toLocaleLowerCase().includes(query) ||
      pageMatches
    );
  });
});

const journalTabs = computed(() => {
  const worldTab = createTab(WORLD_TAB_ID, "World");
  const compendiumTab = createTab(COMPENDIUMS_TAB_ID, "Compendiums");
  const compendiumFolders = new Map<string, JournalFolder>();

  for (const journal of filteredJournals.value) {
    if (journal.source.type === "world") {
      addJournalToWorldTab(worldTab, journal);
    } else {
      addJournalToCompendiumTab(compendiumTab, compendiumFolders, journal);
    }
  }

  sortFolderTree(worldTab.folders);
  sortFolderTree(compendiumTab.folders);

  return [worldTab, compendiumTab];
});

const filteredPageCount = computed(() => {
  return filteredJournals.value.reduce((total, journal) => total + journal.pages.length, 0);
});

const selectedEntry = computed(() => {
  return props.journals.find((journal) => journal.id === selectedEntryId.value);
});

function createTab(id: string, label: string): JournalTab {
  return {
    folders: [],
    id,
    journalCount: 0,
    label,
    pageCount: 0,
  };
}

function createFolder(id: string, name: string): JournalFolder {
  return {
    folders: [],
    id,
    journalCount: 0,
    journals: [],
    name,
    pageCount: 0,
  };
}

function addJournalToWorldTab(tab: JournalTab, journal: MobileJournalEntry): void {
  const folderPath = journal.folderName ?? WORLD_ROOT_FOLDER_NAME;
  addJournalToFolderPath(tab.folders, `${tab.id}:folder`, folderPath, journal);
  addJournalToTab(tab, journal);
}

function addJournalToCompendiumTab(
  tab: JournalTab,
  compendiumFolders: Map<string, JournalFolder>,
  journal: MobileJournalEntry,
): void {
  const rootFolder = getOrCreateCompendiumFolder(tab, compendiumFolders, journal);

  if (journal.folderName) {
    addJournalToFolderPath(
      rootFolder.folders,
      `${rootFolder.id}:folder`,
      journal.folderName,
      journal,
    );
  } else {
    rootFolder.journals.push(journal);
  }

  addJournalToFolderTotals(rootFolder, journal);
  addJournalToTab(tab, journal);
}

function getOrCreateCompendiumFolder(
  tab: JournalTab,
  compendiumFolders: Map<string, JournalFolder>,
  journal: MobileJournalEntry,
): JournalFolder {
  const folderId = `${tab.id}:pack:${journal.source.id}`;
  const existingFolder = compendiumFolders.get(folderId);

  if (existingFolder) {
    return existingFolder;
  }

  const folder = createFolder(folderId, journal.source.label);
  compendiumFolders.set(folderId, folder);
  tab.folders.push(folder);

  return folder;
}

function addJournalToFolderPath(
  folders: JournalFolder[],
  idPrefix: string,
  folderPath: string,
  journal: MobileJournalEntry,
): void {
  const pathSegments = folderPath
    .split("/")
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0);
  const effectivePathSegments = pathSegments.length > 0 ? pathSegments : [NO_FOLDER_NAME];
  let currentFolders = folders;
  let currentFolder: JournalFolder | undefined;
  const idParts: string[] = [];

  for (const pathSegment of effectivePathSegments) {
    idParts.push(pathSegment.toLocaleLowerCase());
    const folderId = `${idPrefix}:${idParts.join(":")}`;
    currentFolder = getOrCreateFolder(currentFolders, folderId, pathSegment);
    addJournalToFolderTotals(currentFolder, journal);
    currentFolders = currentFolder.folders;
  }

  if (currentFolder) {
    currentFolder.journals.push(journal);
  }
}

function getOrCreateFolder(
  folders: JournalFolder[],
  folderId: string,
  folderName: string,
): JournalFolder {
  const existingFolder = folders.find((folder) => folder.id === folderId);

  if (existingFolder) {
    return existingFolder;
  }

  const folder = createFolder(folderId, folderName);
  folders.push(folder);

  return folder;
}

function addJournalToFolderTotals(folder: JournalFolder, journal: MobileJournalEntry): void {
  folder.journalCount += 1;
  folder.pageCount += journal.pages.length;
}

function addJournalToTab(tab: JournalTab, journal: MobileJournalEntry): void {
  tab.journalCount += 1;
  tab.pageCount += journal.pages.length;
}

function sortFolderTree(folders: JournalFolder[]): void {
  folders.sort(compareFolders);

  for (const folder of folders) {
    folder.journals.sort(compareJournals);
    sortFolderTree(folder.folders);
  }
}

function compareFolders(left: JournalFolder, right: JournalFolder): number {
  return left.name.localeCompare(right.name);
}

function compareJournals(left: MobileJournalEntry, right: MobileJournalEntry): number {
  return left.name.localeCompare(right.name);
}

function openEntry(entry: MobileJournalEntry): void {
  selectedEntryId.value = entry.id;
  selectedPageId.value = entry.pages[0]?.id ?? "";
  isReading.value = true;
}

function showList(): void {
  isReading.value = false;
}
</script>

<template>
  <section class="mobile-journal-shell" aria-label="Journal browser">
    <header class="mobile-journal-shell__app-header">
      <div>
        <p>Drowsy's WFRP4e On The Go</p>
        <h1>Journals</h1>
      </div>
      <span class="tw:dui-badge tw:dui-badge-primary">{{ filteredJournals.length }}</span>
    </header>

    <MobileJournalList
      v-if="!isReading"
      v-model:search-text="searchText"
      :journal-count="filteredJournals.length"
      :tabs="journalTabs"
      :total-page-count="filteredPageCount"
      @open-entry="openEntry"
    />

    <MobileJournalReader
      v-else-if="selectedEntry"
      v-model:page-id="selectedPageId"
      :entry="selectedEntry"
      @back="showList"
    />
  </section>
</template>
