import type { PlayerNotes, PlayerPersonalDetail } from "../../../types/player-character";
import { asRecord, readNestedString, readString } from "../value-readers";

const PERSONAL_DETAILS = [
  ["gender", "Gender"],
  ["age", "Age"],
  ["height", "Height"],
  ["weight", "Weight"],
  ["haircolour", "Hair colour"],
  ["eyecolour", "Eye colour"],
  ["distinguishingmark", "Distinguishing mark"],
  ["starsign", "Star sign"],
  ["size", "Size"],
] as const;

export function extractNotes(details: Record<string, unknown>): PlayerNotes {
  const personal = asRecord(details["personal-ambitions"]);
  const party = asRecord(details["party-ambitions"]);
  return {
    biography: readNestedString(details, "biography", "value"),
    motivation: readNestedString(details, "motivation", "value"),
    partyLongTermAmbition: readString(party?.["long-term"]),
    partyName: readString(party?.["name"]),
    partyShortTermAmbition: readString(party?.["short-term"]),
    personalLongTermAmbition: readString(personal?.["long-term"]),
    personalShortTermAmbition: readString(personal?.["short-term"]),
  };
}

export function extractPersonalDetails(details: Record<string, unknown>): PlayerPersonalDetail[] {
  return PERSONAL_DETAILS.map(([key, label]) => ({
    key,
    label,
    value: readNestedString(details, key, "value"),
  }));
}
