<script setup lang="ts">
import { computed } from "vue";

import { usePlayerSheetStore } from "../../state/player-sheet-store";
import type { PlayerActions, PlayerSkill } from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import DescriptionCollapse from "../common/DescriptionCollapse.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";

const props = defineProps<{
  actions: PlayerActions;
  skills: PlayerSkill[];
}>();

const store = usePlayerSheetStore();
const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const filteredSkills = computed(() => {
  const skills = store.trainedSkillsOnly
    ? props.skills.filter((skill) => skill.advances > 0)
    : props.skills;
  const query = store.normalizedSkillFilter;
  return query ? skills.filter((skill) => skill.name.toLocaleLowerCase().includes(query)) : skills;
});

function roll(skill: PlayerSkill): void {
  void runPlayerAction(() => props.actions.rollSkill(skill.id), `${skill.name} test sent to chat.`);
}
</script>

<template>
  <section class="tw:grid tw:gap-3 tw:p-3" aria-label="Skills">
    <SectionHeading :count="filteredSkills.length" eyebrow="Tests at a glance" title="Skills" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />
    <label for="player-skill-filter" class="tw:text-xs tw:font-bold">Filter skills</label>
    <input
      id="player-skill-filter"
      v-model="store.skillFilter"
      type="search"
      class="tw:dui-input tw:min-h-11 tw:w-full"
      placeholder="Name or specialization"
    />
    <label class="tw:flex tw:min-h-11 tw:items-center tw:justify-between tw:gap-3">
      <span class="tw:text-sm tw:font-bold">Trained skills only</span>
      <input
        v-model="store.trainedSkillsOnly"
        type="checkbox"
        class="tw:dui-toggle tw:dui-toggle-secondary"
      />
    </label>

    <div class="tw:grid tw:gap-2">
      <DescriptionCollapse
        v-for="skill in filteredSkills"
        :key="skill.id"
        :description-html="skill.descriptionHtml"
        :subtitle="`${skill.characteristic} · ${skill.advances} advances`"
        :title="skill.name"
      >
        <template #badge>
          <span class="tw:dui-badge tw:dui-badge-secondary tw:font-bold tw:tabular-nums">
            {{ skill.total }}
          </span>
        </template>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-primary tw:min-h-11 tw:w-full"
          :disabled="isBusy"
          @click="roll(skill)"
        >
          <i class="fa-solid fa-dice-d20" aria-hidden="true" />
          Set up {{ skill.name }} test
        </button>
      </DescriptionCollapse>
    </div>
    <p v-if="filteredSkills.length === 0" class="tw:m-0 tw:p-4 tw:text-center tw:opacity-70">
      No skills match that filter.
    </p>
  </section>
</template>
