import { defineStore } from "pinia";
import { computed, ref } from "vue";

export type PlayerSheetDestination =
  | "status"
  | "skills"
  | "abilities"
  | "combat"
  | "inventory"
  | "magic"
  | "religion"
  | "effects"
  | "notes"
  | "advancement"
  | "chat"
  | "journals";

export const usePlayerSheetStore = defineStore("player-sheet", () => {
  const activeDestination = ref<PlayerSheetDestination>("status");
  const menuOpen = ref(false);
  const selectedInventoryItemId = ref<string>();
  const skillFilter = ref("");
  const trainedSkillsOnly = ref(false);

  const normalizedSkillFilter = computed(() => skillFilter.value.trim().toLocaleLowerCase());

  function closeMenu(): void {
    menuOpen.value = false;
  }

  function selectInventoryItem(itemId: string): void {
    selectedInventoryItemId.value = itemId;
  }

  function showDestination(destination: PlayerSheetDestination): void {
    activeDestination.value = destination;
    selectedInventoryItemId.value = undefined;
    closeMenu();
  }

  function showInventoryList(): void {
    selectedInventoryItemId.value = undefined;
  }

  function showAllSkills(): void {
    trainedSkillsOnly.value = false;
  }

  function showTrainedSkills(): void {
    trainedSkillsOnly.value = true;
  }

  return {
    activeDestination,
    closeMenu,
    menuOpen,
    normalizedSkillFilter,
    selectedInventoryItemId,
    selectInventoryItem,
    showAllSkills,
    showDestination,
    showInventoryList,
    showTrainedSkills,
    skillFilter,
    trainedSkillsOnly,
  };
});
