export const MOBILE_SHELL_WINDOW_CLASS = "wfrp-on-the-go-mobile-shell-window";

const ACTIVE_BODY_CLASS = "wfrp-on-the-go-mode-active";
// Application rerenders may activate the same owner repeatedly, while two shells can briefly
// overlap during lifecycle transitions. A Set keeps both cases symmetric on close.
const activeOwners = new Set<object>();

export function activateMobileShellMode(owner: object): void {
  activeOwners.add(owner);
  document.body.classList.add(ACTIVE_BODY_CLASS);
}

export function deactivateMobileShellMode(owner: object): void {
  activeOwners.delete(owner);

  if (activeOwners.size === 0) {
    document.body.classList.remove(ACTIVE_BODY_CLASS);
  }
}
