import type {
  PlayerAilment,
  PlayerCondition,
  PlayerEffect,
  PlayerEffects,
  PlayerExtendedTest,
} from "../../../types/player-character";
import { compareByName } from "../../functions/player-sheet/sorting";
import {
  asRecord,
  readBoolean,
  readDescription,
  readNestedString,
  readNumeric,
  readString,
} from "../value-readers";
import { getCollectionContents, getItemId, getItemSystem } from "./data";

const CONDITION_DEFINITIONS = [
  ["ablaze", "Ablaze"],
  ["bleeding", "Bleeding"],
  ["blinded", "Blinded"],
  ["broken", "Broken"],
  ["deafened", "Deafened"],
  ["entangled", "Entangled"],
  ["fatigued", "Fatigued"],
  ["poisoned", "Poisoned"],
  ["prone", "Prone"],
  ["stunned", "Stunned"],
  ["surprised", "Surprised"],
  ["unconscious", "Unconscious"],
] as const;

const AILMENT_TYPES = new Set(["critical", "disease", "injury", "mutation", "psychology"]);

export function extractPlayerEffects(actor: FoundryActor, items: unknown[]): PlayerEffects {
  const effects = getCollectionContents(actor.appliedEffects ?? actor.effects);

  return {
    active: effects
      .map(extractActiveEffect)
      .filter((effect): effect is PlayerEffect => effect !== undefined)
      .sort(compareByName),
    ailments: items
      .map(extractAilment)
      .filter((item): item is PlayerAilment => item !== undefined)
      .sort(compareByName),
    conditions: extractConditions(effects),
    extendedTests: items
      .map(extractExtendedTest)
      .filter((item): item is PlayerExtendedTest => item !== undefined)
      .sort(compareByName),
  };
}

function extractConditions(effects: unknown[]): PlayerCondition[] {
  const existingById = new Map<string, PlayerCondition>();

  for (const effect of effects) {
    const record = asRecord(effect);

    if (!record || record["isCondition"] !== true) {
      continue;
    }

    const system = asRecord(record["system"]);
    const condition = asRecord(system?.["condition"]);
    const id =
      readString(record["conditionId"]) ||
      readString(record["key"]) ||
      readString(record["statusId"]);

    if (!id) {
      continue;
    }

    existingById.set(id, {
      id,
      imageUrl: readString(record["img"] || record["icon"]),
      name: readString(record["name"]) || titleCase(id),
      value: readNumeric(record["conditionValue"]) ?? readNumeric(condition?.["value"]) ?? 1,
    });
  }

  return CONDITION_DEFINITIONS.map(
    ([id, name]) => existingById.get(id) ?? { id, imageUrl: "", name, value: 0 },
  );
}

function extractActiveEffect(effect: unknown): PlayerEffect | undefined {
  const record = asRecord(effect);

  if (!record || record["isCondition"] === true || record["show"] === false) {
    return undefined;
  }

  const id = readString(record["id"]);
  const name = readString(record["name"]);

  if (!id || !name) {
    return undefined;
  }

  const system = asRecord(record["system"]);

  return {
    descriptionHtml:
      readString(record["description"]) ||
      readDescription(system) ||
      readString(system?.["description"]),
    disabled: readBoolean(record["disabled"]),
    id,
    imageUrl: readString(record["img"] || record["icon"]),
    name,
    source: readString(record["sourceName"] || record["origin"]),
  };
}

function extractAilment(item: unknown): PlayerAilment | undefined {
  const record = asRecord(item);
  const type = readString(record?.["type"]);
  const system = getItemSystem(item);

  if (!record || !system || !AILMENT_TYPES.has(type)) {
    return undefined;
  }

  return {
    descriptionHtml: readDescription(system),
    details: getAilmentDetails(type, system),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    name: readString(record["name"]),
    type: titleCase(type),
  };
}

function getAilmentDetails(
  type: string,
  system: Record<string, unknown>,
): Array<{ label: string; value: string }> {
  const definitions: Record<string, Array<[string, string]>> = {
    critical: [
      ["Wounds", "wounds"],
      ["Location", "location"],
      ["Modifier", "modifier"],
    ],
    disease: [
      ["Contraction", "contraction"],
      ["Incubation", "incubation"],
      ["Duration", "duration"],
      ["Symptoms", "symptoms"],
    ],
    injury: [
      ["Location", "location"],
      ["Penalty", "penalty"],
      ["Duration", "duration"],
    ],
    mutation: [
      ["Type", "mutationType"],
      ["Modifier", "modifier"],
    ],
  };

  return (definitions[type] ?? [])
    .map(([label, key]) => ({ label, value: readNestedString(system, key, "value") }))
    .filter((detail) => detail.value);
}

function extractExtendedTest(item: unknown): PlayerExtendedTest | undefined {
  const record = asRecord(item);
  const system = getItemSystem(item);

  if (record?.["type"] !== "extendedTest" || !system) {
    return undefined;
  }

  const sl = asRecord(system["SL"]);

  return {
    currentSL: readNumeric(sl?.["current"]) ?? 0,
    descriptionHtml: readDescription(system),
    difficulty: readNestedString(system, "difficulty", "value"),
    id: getItemId(item),
    imageUrl: readString(record["img"]),
    name: readString(record["name"]),
    targetSL: readNumeric(sl?.["target"]) ?? 0,
    test: readNestedString(system, "test", "value"),
  };
}

function titleCase(value: string): string {
  return value
    .replaceAll(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/^./, (letter) => letter.toUpperCase());
}
