<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from "vue";
import { readBrowserFullscreenState, toggleBrowserFullscreen } from "./browser-fullscreen";

const state = ref(readBrowserFullscreenState(document));
const pending = ref(false);
const error = ref("");

function sync(): void {
  state.value = readBrowserFullscreenState(document);
}

function onFullscreenChange(): void {
  sync();
  error.value = "";
}

onMounted(() => {
  sync();
  document.addEventListener("fullscreenchange", onFullscreenChange);
});
onBeforeUnmount(() => document.removeEventListener("fullscreenchange", onFullscreenChange));

async function toggle(): Promise<void> {
  if (pending.value) return;
  pending.value = true;
  error.value = "";
  try {
    await toggleBrowserFullscreen(document);
  } catch {
    error.value = "Browser fullscreen was blocked. You can still use On The Go normally.";
  } finally {
    sync();
    pending.value = false;
  }
}
</script>

<template>
  <div class="tw:grid tw:gap-2">
    <button
      type="button"
      class="tw:dui-btn tw:dui-btn-sm tw:h-auto tw:min-h-11 tw:w-full tw:py-2 tw:whitespace-normal"
      :disabled="pending || (!state.supported && !state.active)"
      :aria-pressed="state.active"
      :aria-busy="pending"
      @click="toggle"
    >
      <i class="fa-solid" :class="state.active ? 'fa-compress' : 'fa-expand'" aria-hidden="true" />
      {{ state.active ? "Exit fullscreen" : "Enter fullscreen" }}
    </button>
    <p v-if="!state.supported && !state.active" class="tw:m-0 tw:text-sm">
      Fullscreen is unavailable in this browser or page. Try your browser's fullscreen or toolbar
      controls.
    </p>
    <p v-if="error" role="alert" class="tw:m-0 tw:text-sm">{{ error }}</p>
  </div>
</template>
