import type {
  PlayerInventoryGroup,
  PlayerInventoryItem,
  PlayerInventoryItemType,
} from "../../../types/player-character";

const INVENTORY_GROUP_ORDER: PlayerInventoryGroup[] = [
  "arms-armour",
  "packs-containers",
  "provisions",
  "tools-lore",
  "belongings",
  "coin",
];

export function classifyInventoryItem(
  type: PlayerInventoryItemType,
  trappingType = "",
): { category: string; group: PlayerInventoryGroup } {
  if (type === "weapon") return { category: "Weapon", group: "arms-armour" };
  if (type === "armour") return { category: "Armour", group: "arms-armour" };
  if (type === "ammunition") return { category: "Ammunition", group: "arms-armour" };
  if (type === "container") return { category: "Container", group: "packs-containers" };
  if (type === "money") return { category: "Coin", group: "coin" };

  if (["foodAndDrink", "drugsPoisonsHerbsDraughts", "ingredient"].includes(trappingType)) {
    return { category: "Provision", group: "provisions" };
  }

  if (["booksAndDocuments", "toolsAndKits", "tradeTools"].includes(trappingType)) {
    return { category: "Tool or lore", group: "tools-lore" };
  }

  if (trappingType === "clothingAccessories") {
    return { category: "Clothing", group: "belongings" };
  }

  return { category: "Belonging", group: "belongings" };
}

export function compareInventoryItems(
  left: Pick<PlayerInventoryItem, "group" | "name">,
  right: Pick<PlayerInventoryItem, "group" | "name">,
): number {
  const groupDifference =
    INVENTORY_GROUP_ORDER.indexOf(left.group) - INVENTORY_GROUP_ORDER.indexOf(right.group);

  return groupDifference || left.name.localeCompare(right.name);
}
