import { createPinia } from "pinia";
import { type App, type Component, createApp } from "vue";

// Shared by ordinary applications and Foundry's document-sheet subclasses.
export class VueMount {
  #app: App<Element> | undefined;
  readonly #pinia = createPinia();

  createRoot(): HTMLElement {
    const root = document.createElement("div");
    root.classList.add("wfrp-on-the-go-root");
    root.dataset["theme"] = "wfrp-on-the-go";
    return root;
  }

  mount(
    root: HTMLElement,
    content: HTMLElement,
    component: Component,
    props: Record<string, unknown>,
  ): void {
    this.unmount();
    content.classList.add("wfrp-on-the-go-app");
    content.replaceChildren(root);
    this.#app = createApp(component, props);
    // Document-driven rerenders retain the current destination and inventory selection.
    this.#app.use(this.#pinia);
    this.#app.mount(root);
  }

  unmount(): void {
    this.#app?.unmount();
    this.#app = undefined;
  }
}
