export function canCurrentUserObserve(document: unknown): boolean {
  if (!isRecord(document) || document["visible"] !== true) {
    return false;
  }

  const testUserPermission = document["testUserPermission"];

  if (typeof testUserPermission !== "function") {
    return false;
  }

  try {
    return testUserPermission.call(document, game.user, "OBSERVER") === true;
  } catch {
    return false;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
