<script setup lang="ts">
import { computed, reactive, ref } from "vue";

import type { MobileActivationSettings } from "../../../../types/activation-settings";
import type { MobileJournalEntry } from "../../../../types/mobile-journal";

import BrowserFullscreenButton from "../../common/view/BrowserFullscreenButton.vue";
import MobileJournalApp from "../../mobile-journals/view/MobileJournalApp.vue";

type MobileShellView = "home" | "journals" | "settings";

const props = defineProps<{
  activationSettings: MobileActivationSettings;
  disableForcedMode: () => Promise<void>;
  journals: MobileJournalEntry[];
  saveActivationSettings: (settings: MobileActivationSettings) => Promise<void>;
}>();

const activeView = ref<MobileShellView>("home");
const isSaving = ref(false);
const saveMessage = ref("");
const settings = reactive(cloneActivationSettings(props.activationSettings));
const currentTitle = computed(() => {
  if (activeView.value === "journals") {
    return "Journals";
  }

  if (activeView.value === "settings") {
    return "Settings";
  }

  return "Home";
});

const journalPageCount = computed(() => {
  return props.journals.reduce((total, journal) => total + journal.pages.length, 0);
});

function openView(view: MobileShellView): void {
  activeView.value = view;
  saveMessage.value = "";
}

function goHome(): void {
  activeView.value = "home";
}

function setUserEnabled(userId: string, enabled: boolean): void {
  const user = settings.users.find((candidate) => candidate.id === userId);

  if (user) {
    user.enabled = enabled;
  }
}

function updateUserEnabled(userId: string, event: Event): void {
  const input = event.target;

  if (input instanceof HTMLInputElement) {
    setUserEnabled(userId, input.checked);
  }
}

async function saveSettings(): Promise<void> {
  isSaving.value = true;
  saveMessage.value = "";

  try {
    await props.saveActivationSettings(cloneActivationSettings(settings));
    saveMessage.value = "Saved";
  } finally {
    isSaving.value = false;
  }
}

async function turnOffForcedMode(): Promise<void> {
  isSaving.value = true;
  saveMessage.value = "";

  try {
    settings.forceMobileUi = false;
    await props.disableForcedMode();
    saveMessage.value = "Forced mode is off. Refresh to return to Foundry.";
  } finally {
    isSaving.value = false;
  }
}

function cloneActivationSettings(
  settingsToClone: MobileActivationSettings,
): MobileActivationSettings {
  return {
    forceMobileUi: settingsToClone.forceMobileUi,
    mobileWidthThreshold: settingsToClone.mobileWidthThreshold,
    users: settingsToClone.users.map((user) => ({ ...user })),
  };
}
</script>

<template>
  <main class="on-the-go-shell">
    <header class="on-the-go-shell__top-bar">
      <button
        v-if="activeView !== 'home'"
        type="button"
        class="tw:dui-btn tw:dui-btn-square tw:dui-btn-ghost"
        aria-label="Back to home"
        @click="goHome"
      >
        <i class="fa-solid fa-chevron-left" aria-hidden="true" />
      </button>
      <span v-else class="on-the-go-shell__top-bar-spacer" aria-hidden="true" />
      <div>
        <p>Drowsy's WFRP4e On The Go</p>
        <h1>{{ currentTitle }}</h1>
      </div>
      <span class="on-the-go-shell__top-bar-spacer" aria-hidden="true" />
    </header>

    <section v-if="activeView === 'home'" class="on-the-go-shell__home" aria-label="Main menu">
      <button
        type="button"
        class="on-the-go-shell__menu-button tw:dui-card"
        @click="openView('journals')"
      >
        <i class="fa-solid fa-book-open" aria-hidden="true" />
        <span>
          <strong>Journals</strong>
          <small>{{ journals.length }} entries, {{ journalPageCount }} pages</small>
        </span>
      </button>

      <button
        type="button"
        class="on-the-go-shell__menu-button tw:dui-card"
        @click="openView('settings')"
      >
        <i class="fa-solid fa-sliders" aria-hidden="true" />
        <span>
          <strong>Settings</strong>
          <small>{{
            settings.forceMobileUi ? "Forced on this client" : "Automatic activation"
          }}</small>
        </span>
      </button>
      <BrowserFullscreenButton />
    </section>

    <section v-else-if="activeView === 'journals'" class="on-the-go-shell__content">
      <MobileJournalApp :journals="journals" />
    </section>

    <form v-else class="on-the-go-shell__settings" @submit.prevent="saveSettings">
      <label class="on-the-go-shell__toggle tw:dui-card">
        <span>
          <strong>Force On This Client</strong>
          <small>{{ settings.forceMobileUi ? "On" : "Off" }}</small>
        </span>
        <input
          v-model="settings.forceMobileUi"
          type="checkbox"
          class="tw:dui-toggle tw:dui-toggle-primary"
        />
      </label>

      <label class="on-the-go-shell__field">
        <span>Mobile Width Threshold</span>
        <input
          v-model.number="settings.mobileWidthThreshold"
          type="number"
          min="320"
          max="1400"
          step="10"
          class="tw:dui-input"
        />
      </label>

      <section class="on-the-go-shell__gm-list" aria-label="Enabled users">
        <h2>Enabled Users</h2>
        <label
          v-for="user in settings.users"
          :key="user.id"
          class="on-the-go-shell__toggle tw:dui-card"
          :class="{ 'on-the-go-shell__toggle--current': user.isCurrentUser }"
        >
          <span>
            <strong>{{ user.name }}</strong>
            <small>
              {{ user.isGm ? "GM" : "Player" }}{{ user.isCurrentUser ? " · Current user" : "" }}
            </small>
          </span>
          <input
            type="checkbox"
            class="tw:dui-toggle tw:dui-toggle-primary"
            :checked="user.enabled"
            @change="updateUserEnabled(user.id, $event)"
          />
        </label>
      </section>

      <footer class="on-the-go-shell__actions">
        <p aria-live="polite">{{ saveMessage }}</p>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-outline"
          :disabled="isSaving"
          @click="turnOffForcedMode"
        >
          <i class="fa-solid fa-power-off" aria-hidden="true" />
          <span>Turn Off Forced Mode</span>
        </button>
        <button type="submit" class="tw:dui-btn tw:dui-btn-primary" :disabled="isSaving">
          <i class="fa-solid fa-floppy-disk" aria-hidden="true" />
          <span>{{ isSaving ? "Saving" : "Save" }}</span>
        </button>
      </footer>
    </form>
  </main>
</template>
