<script setup lang="ts">
import { computed } from "vue";

import { type PlayerSheetDestination, usePlayerSheetStore } from "../../state/player-sheet-store";
import type { PlayerCharacterState } from "../../../../../types/player-character";

const props = defineProps<{
  characterState: PlayerCharacterState;
}>();

const store = usePlayerSheetStore();
const labels: Record<PlayerSheetDestination, string> = {
  abilities: "Talents & Traits",
  advancement: "Advancement",
  chat: "Chat & Results",
  combat: "Combat",
  effects: "Effects & Health",
  inventory: "Inventory",
  journals: "Journals",
  magic: "Magic",
  notes: "Notes & Record",
  religion: "Religion",
  skills: "Skills",
  status: "Status",
};
const sheetStatusLabel = computed(() => {
  if (props.characterState.status === "ready") return "Live character linked";
  if (props.characterState.status === "missing") return "No character assigned";
  return "Character needs attention";
});
</script>

<template>
  <header
    class="tw:dui-navbar tw:min-h-14 tw:border-b tw:border-secondary/50 tw:bg-neutral tw:px-2 tw:py-2 tw:text-neutral-content"
  >
    <div class="tw:dui-navbar-start tw:w-auto">
      <button
        type="button"
        class="tw:dui-btn tw:dui-btn-ghost tw:dui-btn-sm tw:min-h-11"
        :disabled="characterState.status !== 'ready'"
        :aria-expanded="store.menuOpen"
        aria-controls="player-adventure-menu-panel"
        @click="store.menuOpen = true"
      >
        <i class="fa-solid fa-bars" aria-hidden="true" />
        Menu
      </button>
    </div>
    <div class="tw:dui-navbar-center tw:min-w-0 tw:flex-1 tw:px-2">
      <div class="tw:min-w-0 tw:text-center">
        <p
          class="tw:m-0 tw:text-[0.6rem] tw:font-black tw:tracking-[0.14em] tw:text-secondary tw:uppercase"
        >
          WFRP4e On The Go
        </p>
        <strong class="tw:block tw:truncate tw:font-serif tw:text-base">
          {{ labels[store.activeDestination] }}
        </strong>
      </div>
    </div>
    <div class="tw:dui-navbar-end tw:w-auto">
      <span class="tw:dui-tooltip tw:dui-tooltip-left" :data-tip="sheetStatusLabel">
        <span class="tw:dui-badge tw:dui-badge-ghost tw:dui-badge-sm" role="status">
          <span
            class="tw:dui-status tw:dui-status-sm"
            :class="{
              'tw:dui-status-success': characterState.status === 'ready',
              'tw:dui-status-warning': characterState.status === 'missing',
              'tw:dui-status-error': characterState.status === 'unsupported',
            }"
            aria-hidden="true"
          />
          <span class="tw:sr-only">{{ sheetStatusLabel }}</span>
        </span>
      </span>
    </div>
  </header>
</template>
