import { registerPackageApi } from "../foundry/api/register-package-api";
import { PACKAGE_ID, WFRP4E_SYSTEM_ID } from "../constants";
import { openMobileUiIfActive } from "../foundry/open-mobile-ui";
import { registerModuleSettings } from "../foundry/settings/register-module-settings";
import { migrateActivationSettings } from "../foundry/settings/activation-settings";

export function registerModuleHooks(): void {
  Hooks.once("init", () => {
    registerModuleSettings();
  });

  Hooks.once("ready", async () => {
    if (game.system.id !== WFRP4E_SYSTEM_ID) {
      console.warn(`${PACKAGE_ID} | Loaded outside ${WFRP4E_SYSTEM_ID}; activation skipped.`);
      return;
    }

    await migrateActivationSettings();
    registerPackageApi();
    await openMobileUiIfActive();
  });
}
