<script setup lang="ts">
import { computed, ref } from "vue";

import { usePlayerSheetStore } from "../../state/player-sheet-store";
import type {
  PlayerActions,
  PlayerInventory,
  PlayerInventoryGroup,
  PlayerInventoryItemType,
} from "../../../../../types/player-character";
import ActionStatus from "../common/ActionStatus.vue";
import SectionHeading from "../common/SectionHeading.vue";
import { usePlayerAction } from "../usePlayerAction";
import InventoryItemDetail from "./InventoryItemDetail.vue";

const props = defineProps<{
  actions: PlayerActions;
  inventory: PlayerInventory;
}>();

const store = usePlayerSheetStore();
const { actionMessage, actionTone, isBusy, runPlayerAction } = usePlayerAction();
const newItemName = ref("");
const newItemType = ref<PlayerInventoryItemType>("trapping");
const groups: Array<{ id: PlayerInventoryGroup; label: string }> = [
  { id: "arms-armour", label: "Arms & Armour" },
  { id: "packs-containers", label: "Packs & Containers" },
  { id: "provisions", label: "Provisions" },
  { id: "tools-lore", label: "Tools & Lore" },
  { id: "belongings", label: "Belongings" },
  { id: "coin", label: "Coin" },
];
const inventoryGroups = computed(() =>
  groups
    .map((group) => ({
      ...group,
      items: props.inventory.items.filter((item) => item.group === group.id),
    }))
    .filter((group) => group.items.length > 0),
);
const selectedItem = computed(() =>
  props.inventory.items.find((item) => item.id === store.selectedInventoryItemId),
);
const containers = computed(() =>
  props.inventory.items.filter((item) => item.type === "container"),
);
const encumbrancePercentage = computed(() =>
  props.inventory.maximumEncumbrance > 0
    ? Math.max(
        0,
        Math.min(
          100,
          (props.inventory.currentEncumbrance / props.inventory.maximumEncumbrance) * 100,
        ),
      )
    : 0,
);

function createItem(): void {
  void runPlayerAction(
    () => props.actions.createInventoryItem({ name: newItemName.value, type: newItemType.value }),
    `${newItemName.value.trim()} created.`,
  ).then(() => {
    if (actionTone.value === "success") newItemName.value = "";
  });
}
</script>

<template>
  <InventoryItemDetail
    v-if="selectedItem"
    :actions="actions"
    :containers="containers"
    :item="selectedItem"
    @back="store.showInventoryList"
  />

  <section v-else class="tw:grid tw:gap-4 tw:p-3" aria-label="Inventory">
    <SectionHeading :count="inventory.items.length" eyebrow="Pack and purse" title="Inventory" />
    <ActionStatus :message="actionMessage" :tone="actionTone" />

    <section
      class="tw:rounded-box tw:border tw:border-secondary/35 tw:bg-base-200 tw:p-3 tw:shadow-inner"
    >
      <div class="tw:flex tw:items-baseline tw:justify-between tw:gap-3">
        <h3 class="tw:m-0 tw:text-sm tw:font-bold">Encumbrance</h3>
        <strong class="tw:font-serif tw:text-lg tw:tabular-nums">
          {{ inventory.currentEncumbrance }} / {{ inventory.maximumEncumbrance }}
        </strong>
      </div>
      <progress
        class="tw:dui-progress tw:mt-2"
        :class="{
          'tw:dui-progress-warning': inventory.currentEncumbrance >= inventory.maximumEncumbrance,
        }"
        :value="encumbrancePercentage"
        max="100"
        aria-label="Current encumbrance"
      />
    </section>

    <details
      class="tw:dui-collapse tw:dui-collapse-arrow tw:rounded-box tw:border tw:border-base-300 tw:bg-base-200"
    >
      <summary class="tw:dui-collapse-title tw:font-bold">Create a simple item</summary>
      <form class="tw:dui-collapse-content tw:grid tw:gap-3" @submit.prevent="createItem">
        <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold">
          Name
          <input v-model="newItemName" class="tw:dui-input tw:min-h-11 tw:w-full" required />
        </label>
        <label class="tw:grid tw:gap-1 tw:text-sm tw:font-bold">
          Type
          <select v-model="newItemType" class="tw:dui-select tw:min-h-11 tw:w-full">
            <option value="trapping">Trapping</option>
            <option value="weapon">Weapon</option>
            <option value="armour">Armour</option>
            <option value="ammunition">Ammunition</option>
            <option value="container">Container</option>
            <option value="money">Money</option>
          </select>
        </label>
        <button
          type="submit"
          class="tw:dui-btn tw:dui-btn-primary tw:min-h-11"
          :disabled="isBusy || !newItemName.trim()"
        >
          <i class="fa-solid fa-plus" aria-hidden="true" /> Create item
        </button>
      </form>
    </details>

    <div class="tw:grid tw:gap-4">
      <section v-for="group in inventoryGroups" :key="group.id">
        <div class="tw:mb-2 tw:flex tw:items-center tw:justify-between tw:px-1">
          <h3 class="tw:m-0 tw:font-serif tw:text-base tw:font-bold">{{ group.label }}</h3>
          <span class="tw:text-xs tw:font-bold tw:opacity-55">{{ group.items.length }}</span>
        </div>
        <ul
          class="tw:dui-list tw:m-0 tw:overflow-hidden tw:rounded-box tw:border tw:border-base-300 tw:bg-base-200 tw:p-0 tw:[list-style:none]"
        >
          <li
            v-for="item in group.items"
            :key="item.id"
            class="tw:dui-list-row tw:block tw:border-b tw:border-base-300 tw:p-0 last:tw:border-b-0"
          >
            <button
              type="button"
              class="tw:dui-btn tw:dui-btn-ghost tw:grid tw:h-auto tw:min-h-16 tw:w-full tw:grid-cols-[auto_minmax(0,1fr)_auto] tw:gap-3 tw:rounded-none tw:p-3 tw:text-left tw:text-base-content"
              @click="store.selectInventoryItem(item.id)"
            >
              <span
                class="tw:grid tw:size-11 tw:place-items-center tw:overflow-hidden tw:rounded-field tw:bg-base-300 tw:text-secondary"
              >
                <img
                  v-if="item.imageUrl"
                  :src="item.imageUrl"
                  alt=""
                  width="44"
                  height="44"
                  class="tw:h-full tw:w-full tw:object-cover"
                />
                <i v-else class="fa-solid fa-sack-xmark" aria-hidden="true" />
              </span>
              <span class="tw:min-w-0">
                <strong class="tw:block tw:[overflow-wrap:anywhere]">{{ item.name }}</strong>
                <small class="tw:flex tw:flex-wrap tw:gap-x-2 tw:opacity-65">
                  <span>{{ item.category }}</span
                  ><span>Enc {{ item.encumbrance }}</span>
                  <span v-if="item.equipped" class="tw:font-bold tw:text-secondary">Equipped</span>
                </small>
              </span>
              <span class="tw:grid tw:justify-items-end tw:gap-1">
                <span class="tw:dui-badge tw:dui-badge-sm tw:tabular-nums"
                  >×{{ item.quantity }}</span
                >
                <i class="fa-solid fa-chevron-right tw:text-xs tw:opacity-45" aria-hidden="true" />
              </span>
            </button>
          </li>
        </ul>
      </section>
    </div>
    <div v-if="inventory.items.length === 0" class="tw:dui-alert" role="status">
      No carried items yet.
    </div>
  </section>
</template>
