<script setup lang="ts">
import { ref } from "vue";

withDefaults(
  defineProps<{
    body: string;
    confirmLabel?: string;
    danger?: boolean;
    icon?: string;
    title: string;
    triggerLabel: string;
  }>(),
  { confirmLabel: "Confirm", danger: true, icon: "fa-solid fa-trash" },
);

const emit = defineEmits<{
  confirm: [];
}>();
const dialog = ref<HTMLDialogElement>();

function confirm(): void {
  dialog.value?.close();
  emit("confirm");
}
</script>

<template>
  <button
    type="button"
    class="tw:dui-btn tw:min-h-11"
    :class="danger ? 'tw:dui-btn-outline tw:dui-btn-error' : 'tw:dui-btn-primary'"
    @click="dialog?.showModal()"
  >
    <i :class="icon" aria-hidden="true" />
    {{ triggerLabel }}
  </button>
  <dialog ref="dialog" class="tw:dui-modal">
    <div class="tw:dui-modal-box tw:bg-base-200">
      <h3 class="tw:m-0 tw:font-serif tw:text-xl tw:font-bold">{{ title }}</h3>
      <p>{{ body }}</p>
      <div class="tw:dui-modal-action">
        <form method="dialog">
          <button type="submit" class="tw:dui-btn">Cancel</button>
        </form>
        <button
          type="button"
          class="tw:dui-btn"
          :class="danger ? 'tw:dui-btn-error' : 'tw:dui-btn-primary'"
          @click="confirm"
        >
          {{ confirmLabel }}
        </button>
      </div>
    </div>
    <form method="dialog" class="tw:dui-modal-backdrop">
      <button type="submit">Close</button>
    </form>
  </dialog>
</template>
